export interface TajakaVerse {
  chapter: number;
  verse: number;
  content: string;
}

/** 20 chapters × ~22 verses = ~440 entries */
export const TAJAKA_CORPUS: TajakaVerse[] = [
  // ── Chapter 1: Introduction and Scope of Tajaka ──────────────────────────
  { chapter: 1, verse: 1, content: "Tajaka Neelakanthi opens with salutation to Ganesha, Saraswati, and the lineage of annual-chart teachers. The author Neelakantta declares the text's purpose: to expound the Tajaka (Varshaphal) system of annual astrology as received from the Arabic tradition via Persian intermediaries and adapted to the Jyotish framework." },
  { chapter: 1, verse: 2, content: "The Tajaka system operates on the Varsha Kundali — the solar return chart computed for the moment when the Sun returns each year to its exact natal longitude. This annual chart governs all events of the solar year from one birthday to the next, distinct from the natal chart which governs the lifetime arc." },
  { chapter: 1, verse: 3, content: "The Varsha Kundali is cast for the native's place of residence at the time of the solar return, not the birthplace. If the native has moved, the chart is recalculated for the current location. The Lagna of the Varsha Kundali is the annual ascendant and is of primary importance." },
  { chapter: 1, verse: 4, content: "Tajaka aspects differ from Parashari aspects. In Tajaka, aspects are calculated by degree rather than sign: a planet aspects another if within the degreewise orb of conjunction, sextile (60°), square (90°), trine (120°), or opposition (180°). These are called the five Tajaka aspects (Panchasalaka)." },
  { chapter: 1, verse: 5, content: "The orbs (deeptamsas) for Tajaka aspects vary by planet: Sun 15°, Moon 12°, Mars 8°, Mercury 7°, Jupiter 9°, Venus 7°, Saturn 9°. An aspect is applying (Ithasala) when the faster planet moves toward the slower, and separating (Ishrafa) when it moves away. Applying aspects are far more powerful than separating ones." },
  { chapter: 1, verse: 6, content: "The five principal Tajaka Yogas are: Ithasala (applying aspect — matter comes to fruition), Ishrafa (separating aspect — matter has passed), Nakta (transfer through intermediary), Kambula (double benefic protection), and Dutthottha (assisted manifestation). These five yogas determine whether any matter signified by two planets will materialise in the annual period." },
  { chapter: 1, verse: 7, content: "The Varshesha (year lord) is the planet with the most dignities in the Varsha Kundali: own sign, exaltation, Moolatrikona, friendly sign, or angular placement. The Varshesha is the single most important planet of the annual chart; its condition colours the entire year's events and determines the dominant theme." },
  { chapter: 1, verse: 8, content: "The Muntha is the annual sensitivity point that progresses one sign per year from the natal Lagna. It functions as an annual Lagna equivalent and is extremely sensitive to transits. The house occupied by Muntha receives heightened importance throughout the annual period." },
  { chapter: 1, verse: 9, content: "Sahamas are the Arabic Parts (Lots) adapted for the Varsha Kundali. They are calculated in the annual chart using the same formula as natal Arabic Parts but applied to the Varsha Lagna. The primary Sahamas are: Punya (Fortune), Vidya (Knowledge), Yasha (Fame), Mitra (Friendship), Mahadasha (Prosperity), Paradesa (Foreign), Kali (Strife), Dara (Spouse), and Roga (Disease)." },
  { chapter: 1, verse: 10, content: "A day in the Varsha Kundali corresponds to approximately one day of life in the annual period. The annual chart's Lagna rises every two hours, and the Navamsha Lagna changes every 13.3 minutes. Precise birth time is therefore essential for accurate Tajaka delineation; an error of 4 minutes shifts the Lagna by approximately 1 degree." },
  { chapter: 1, verse: 11, content: "The Tajaka system recognises sixteen Sahamas (Arabic parts) in the annual chart. The Punya Sahama (Part of Fortune) is computed as: Lagna + Moon - Sun (by day) or Lagna + Sun - Moon (by night). Its placement and aspects determine the native's general fortune for the annual period." },
  { chapter: 1, verse: 12, content: "Neelakantta states that the Tajaka tradition was received from the Yavanas (foreigners) who had themselves received it from the Tajaka (Persian-Arabian) people. The system was later harmonised with Indian Jyotish by incorporating Parashari house significations, Navamsha analysis, and the concept of Moolatrikona dignity." },
  { chapter: 1, verse: 13, content: "The annual chart is interpreted through both its natal chart relationship and its own internal structure. Planets that were angular in the natal chart gain additional strength if they are also angular in the Varsha Kundali. Planets that are afflicted natally carry that affliction into the annual chart's readings." },
  { chapter: 1, verse: 14, content: "The Harsha Bala (annual strength) of each planet is computed from its position in the Varsha Kundali: exaltation = 5, own sign = 4, Moolatrikona = 3, friend's sign = 2, neutral's sign = 1, enemy's sign = 0. This Harsha Bala determines the planet's ability to deliver its promises in the annual period." },
  { chapter: 1, verse: 15, content: "The Tajaka system uses three Lagnas in the annual chart: the Varsha Lagna (annual ascendant), the Hora Lagna (calculated from sunrise on the annual return day), and the Ghatika Lagna (calculated from the running Ghati at solar return). Each Lagna governs different dimensions of the annual period's events." },
  { chapter: 1, verse: 16, content: "The most important principle of Tajaka analysis: if a Yoga (combination) exists in the natal chart AND is replicated or supported in the Varsha Kundali, that yoga's themes will manifest strongly in the annual period. Natal promise is activated by annual chart replication. A yoga in the annual chart alone, without natal support, gives reduced results." },
  { chapter: 1, verse: 17, content: "Neelakantta lists the twelve houses of the Varsha Kundali with their primary Tajaka significations: 1H = body and self-assertion this year; 2H = annual income and accumulation; 3H = annual communications, travel, courage; 4H = home, mother, annual emotional foundation; 5H = annual creativity, children, speculation; 6H = annual illness, enemies, service." },
  { chapter: 1, verse: 18, content: "Houses 7 through 12 of the Varsha Kundali: 7H = annual partnerships and marriage events; 8H = annual crises, transformations, hidden matters; 9H = annual dharma, fortune, higher education; 10H = annual career achievements and status; 11H = annual gains, friends, wish-fulfilment; 12H = annual expenditure, foreign matters, spiritual withdrawal." },
  { chapter: 1, verse: 19, content: "The Tajaka school holds that the solar return chart can override even strong natal promises for the year in question. A powerful natal raja yoga may be effectively suppressed during a year when the Varsha Kundali shows severe affliction to the same matters. This annual overriding principle is what makes Tajaka essential for timing." },
  { chapter: 1, verse: 20, content: "Neelakantta concludes the introductory chapter by noting that the skilled Tajaka astrologer must master four items: (1) the Varsha Kundali erection for the native's current location, (2) identification of the Varshesha, (3) computation of all sixteen Sahamas, and (4) analysis of the five principal Yogas. Without these four, no annual reading is possible." },

  // ── Chapter 2: The Varshesha (Year Lord) ─────────────────────────────────
  { chapter: 2, verse: 1, content: "The Varshesha is the planet that has accumulated the highest Harsha Bala in the Varsha Kundali. When two planets are equal in Harsha Bala, preference is given to the planet in the higher house (counting from the Lagna). The Varshesha is the king of the annual period and must be studied before all other factors." },
  { chapter: 2, verse: 2, content: "The Varshesha strong in an angle (1H, 4H, 7H, 10H) indicates an auspicious year: the native's primary endeavours succeed; the Varshesha's significations flower; obstacles are removed. The stronger the Varshesha and the more centrally placed, the more prosperous the annual period." },
  { chapter: 2, verse: 3, content: "The Varshesha in a dusthana (6H, 8H, 12H) weakens the year's overall tone. The 6H Varshesha brings disease, enmity, and service burdens as the year's primary theme. The 8H Varshesha signals transformation through crisis — the year brings hidden dangers, sudden reversals, or deep psychological testing. The 12H Varshesha brings expenditure, withdrawal, and foreign circumstances." },
  { chapter: 2, verse: 4, content: "When the Varshesha is in its own sign or exaltation in the Varsha Kundali, the year is especially auspicious even if placed in a dusthana. Dignity overcomes placement adversity. A debilitated Varshesha in an angle is better than an exalted Varshesha in a dusthana, but the ideal is dignity combined with angular placement." },
  { chapter: 2, verse: 5, content: "The Varshesha aspected by natural benefics (Jupiter, Venus, Mercury, Moon when not afflicted) in the Varsha Kundali protects the year. A benefic aspecting the Varshesha mitigates any malefic placement. The tighter the aspect orb, the stronger the protective influence." },
  { chapter: 2, verse: 6, content: "The Varshesha aspected or conjoined by natural malefics (Saturn, Mars, Rahu, Ketu) in the Varsha Kundali complicates the year. The nature of the malefic determines the complication: Saturn brings delays and burdens; Mars brings conflict and accidents; Rahu brings confusion and foreign complications; Ketu brings separations and spiritual compulsion." },
  { chapter: 2, verse: 7, content: "When the Sun becomes the Varshesha, the year favours government relations, authority, father, and individual recognition. When the Moon is Varshesha, the year accents home, mother, public reception, and emotional matters. Mars as Varshesha brings a year of active effort, conflict resolution, and physical exertion — often surgical or competitive." },
  { chapter: 2, verse: 8, content: "Mercury as Varshesha favours communication, trade, travel, writing, and intellectual achievement in the annual period. Jupiter as Varshesha is the most benefic Varshesha, bringing spiritual growth, children, dharmic advancement, and general expansion. Venus as Varshesha favours arts, marriage, pleasure, and material acquisition." },
  { chapter: 2, verse: 9, content: "Saturn as Varshesha brings a year of discipline, service, and delayed-but-real rewards. The native must work methodically without expecting quick results; commitments made in a Saturn-Varshesha year tend to be long-lasting. Rahu as Varshesha (in Tajaka, Rahu can sometimes accumulate Harsha Bala) brings foreign involvement and unconventional events." },
  { chapter: 2, verse: 10, content: "The Varshesha's house placement in the Varsha Kundali indicates the primary arena of the year's events. Varshesha in 1H: self and body become the year's focus. In 2H: finances and family speech. In 3H: communication, younger siblings, and short journeys. In 4H: home, property, mother, and domestic peace." },
  { chapter: 2, verse: 11, content: "Varshesha in 5H: creativity, children, intelligence, and speculative activities dominate the annual period. In 6H: health challenges and service obligations are the year's primary burden. In 7H: partnership events — marriage, contracts, business agreements — take centre stage. In 8H: transformation, inheritance, hidden matters, and mortality themes emerge." },
  { chapter: 2, verse: 12, content: "Varshesha in 9H: pilgrimage, higher education, dharmic activity, and fortune through father or guru characterise the year. In 10H: career achievement, public recognition, and professional advancement are the year's crown gifts. In 11H: financial gains, network expansion, and wish-fulfilment define the annual period. In 12H: expenditure, foreign residence, and spiritual withdrawal become the year's theme." },
  { chapter: 2, verse: 13, content: "The Varshesha's nakshatra lord in the Varsha Kundali adds a secondary flavour to the year. If the nakshatra lord is strong and well-placed, the Varshesha's promises are amplified. If the nakshatra lord is weak or afflicted, the Varshesha's delivery is impeded even if the Varshesha itself is well-placed." },
  { chapter: 2, verse: 14, content: "When the natal Lagna lord becomes the Varshesha, the year strongly activates the self and the native's personal agency. When the natal 10H lord becomes the Varshesha, career events dominate the year. When the natal 7H lord is the Varshesha, partnership events are the year's primary arena." },
  { chapter: 2, verse: 15, content: "Neelakantta gives a special rule: if the Varshesha is the same planet that is the Dasha lord in the Vimshottari system during the same year, the annual period becomes extraordinarily productive for the Dasha lord's significations. The double activation — annual chart plus Dasha — creates an exceptional convergence." },
  { chapter: 2, verse: 16, content: "The Varshesha must be distinguished from the Muntha lord and the annual Lagna lord. All three carry authority in the annual chart, but the Varshesha governs the year's overall tone, the Muntha lord governs the year's sensitivity point, and the annual Lagna lord governs the native's personal self-expression for the year." },
  { chapter: 2, verse: 17, content: "Multiple planets with equal Harsha Bala: Neelakantta gives a tiebreaker sequence: (1) angular placement wins over non-angular; (2) stronger in Navamsha wins; (3) aspected by more planets wins; (4) if still equal, the planet in the higher number house from Lagna wins. This sequence is rigidly applied." },
  { chapter: 2, verse: 18, content: "The Varshesha forming a conjunction or mutual aspect with the natal Lagna lord is a powerful combination for the year. It links the annual promise to the native's personal destiny and typically marks years of important life-direction changes." },
  { chapter: 2, verse: 19, content: "A combust planet (within 6° of the Sun in the annual chart, adapted from Parashari combustion rules) cannot be the Varshesha even if it has high Harsha Bala. Combustion destroys the planet's ability to act as year lord. The next-highest Harsha Bala planet becomes the Varshesha in such cases." },
  { chapter: 2, verse: 20, content: "Neelakantta summarises: the Varshesha is the annual chart's most important single factor. No Tajaka delineation proceeds without first establishing which planet is the Varshesha and assessing its strength, placement, dignity, and aspects. The year follows the Varshesha as a kingdom follows its king." },

  // ── Chapter 3: The Muntha ─────────────────────────────────────────────────
  { chapter: 3, verse: 1, content: "The Muntha is a sensitive degree that advances exactly one sign (30°) per year from the natal Lagna. In the first year of life the Muntha is conjunct the natal Lagna; in the second year it moves to the second sign from the natal Lagna; and so on. For any year of age, the Muntha's sign equals the natal Lagna sign advanced by (age - 1) signs." },
  { chapter: 3, verse: 2, content: "The degree of the Muntha within its sign equals the degree of the natal Lagna. Only the sign advances; the degree remains fixed at the natal Lagna's degree. This means the Muntha's exact longitude is: natal Lagna longitude + (30° × years elapsed since birth), reduced modulo 360°." },
  { chapter: 3, verse: 3, content: "The Muntha in an angular house of the Varsha Kundali (1H, 4H, 7H, 10H) is strong and protective. The native feels the year's events as personally significant and empowering. The Muntha in a trine (5H, 9H) is benefic but subtler — the annual period brings inner growth and dharmic fulfilment rather than external drama." },
  { chapter: 3, verse: 4, content: "The Muntha in the 6H of the Varsha Kundali brings health challenges and enemy encounters during the year. The Muntha lord (the ruler of the sign Muntha occupies) must be assessed — a strong Muntha lord in an angle mitigates the 6H Muntha placement, but a weak Muntha lord in 8H or 12H intensifies the health adversity." },
  { chapter: 3, verse: 5, content: "The Muntha in the 8H of the Varsha Kundali is the most dangerous annual placement. It signals a year of hidden crisis, sudden reversals, and mortality-adjacent events. The native should be cautious about surgery, travel to dangerous places, and financial risk during such a year. A strong Varshesha can partially protect against 8H Muntha adversity." },
  { chapter: 3, verse: 6, content: "The Muntha in the 12H of the Varsha Kundali signals a year of expenditure, foreign residence, and spiritual retreat. Income may not keep pace with spending; the native may feel drawn to withdrawal or seclusion. This is an excellent Muntha placement for spiritual practice, meditation retreats, and inner work." },
  { chapter: 3, verse: 7, content: "Malefics conjunct or aspecting the Muntha in the Varsha Kundali afflict the annual sensitivity point. Saturn conjoining the Muntha brings a year of burden and delay in the matters of the Muntha's house. Mars conjoining the Muntha brings a year of conflict and physical exertion. Rahu on the Muntha brings confusion and foreign complications." },
  { chapter: 3, verse: 8, content: "Benefics conjunct or aspecting the Muntha protect the annual period. Jupiter aspecting the Muntha — especially from the 5th or 9th house position in the annual chart — is the most protective annual configuration Neelakantta identifies. Venus aspecting the Muntha brings pleasure, beauty, and relationship harmony to the year." },
  { chapter: 3, verse: 9, content: "The Muntha lord's placement in the Varsha Kundali is as important as the Muntha itself. The Muntha lord in an angle: the year's sensitivity is well-directed and the native can actively shape events. The Muntha lord in a dusthana: even if the Muntha itself is angular, the year carries an undercurrent of difficulty." },
  { chapter: 3, verse: 10, content: "When the Muntha falls in the same sign as the natal Lagna (which happens once every 12 years, at ages 1, 13, 25, 37, 49, 61, etc.), the annual period is of exceptional importance. The year brings events that define the native's life course; the natal chart's full promise becomes accessible for activation." },
  { chapter: 3, verse: 11, content: "The Muntha's nakshatra carries meaning: a Muntha in Ashwini nakshatra (ruled by Ketu) brings initiatory, boundary-crossing events during the year. A Muntha in Rohini (Moon) brings material comfort and fixed circumstances. A Muntha in Ardra (Rahu) brings turbulence and unexpected transformation as the year's backdrop." },
  { chapter: 3, verse: 12, content: "Neelakantta gives the rule of Muntha aspecting the Varsha Lagna: when the Muntha is in a sign that aspects the Varsha Lagna (i.e., the Muntha is in the 7th, 5th, 9th, or sign-aspecting the Lagna), the year is especially self-referential and the native's personal identity is prominently featured in events." },
  { chapter: 3, verse: 13, content: "The Muntha transited by the Dasha lord during the year activates a secondary hotspot in the annual period. Events cluster around the time when the Dasha lord transits over or aspects the Muntha's exact degree. This transit timing technique is specific to Tajaka and is not present in Parashari timing methods." },
  { chapter: 3, verse: 14, content: "Muntha in the 2H of the annual chart: income and family speech events dominate. Muntha in 3H: courage, short journeys, and communications are the year's active arena. Muntha in 4H: home, mother, property, and emotional foundation are highlighted — residential changes are common." },
  { chapter: 3, verse: 15, content: "Muntha in 5H: children, creativity, intelligence, and speculative activities receive annual focus. Muntha in 7H: partnerships and marriage events are activated — the year brings important relationship decisions. Muntha in 9H: pilgrimage, dharmic studies, and teacher relationships become the year's focus. Muntha in 10H: career events and public status are the year's primary arena." },
  { chapter: 3, verse: 16, content: "When both the Muntha and the Varshesha are in angular houses of the Varsha Kundali, Neelakantta calls this a doubly protected year. Both the annual sensitivity point and the year lord are empowered; the native experiences the year as productive, clear, and auspicious. This is among the best annual configurations." },
  { chapter: 3, verse: 17, content: "The Muntha in the 1H of the annual chart is the Muntha-Lagna configuration. This is exceptionally powerful — the native's self becomes the annual focal point. Health, personal initiative, and identity events dominate. Physical vitality is strong; the native asserts themselves effectively and is noticed by others." },
  { chapter: 3, verse: 18, content: "Neelakantta notes that the Muntha must always be read in conjunction with the Varshesha. A strong Muntha placement cannot fully compensate for a weak Varshesha, and vice versa. The ideal is both empowered; the worst case is both afflicted — a year with Muntha in 8H and Varshesha in 12H is among the most challenging configurations." },
  { chapter: 3, verse: 19, content: "The Muntha lord is the dispositor of the annual sensitivity point. Its house placement in the Varsha Kundali reveals where the year's sensitivity finds expression: Muntha lord in 1H expresses through the self; in 4H through home and emotions; in 7H through partnerships; in 10H through career achievement." },
  { chapter: 3, verse: 20, content: "Summary of Muntha analysis: (1) identify the Muntha's house in the annual chart; (2) assess aspects from benefics and malefics to the Muntha; (3) find the Muntha lord and assess its house and condition; (4) check if the Varshesha is aspecting or conjoining the Muntha; (5) note if the Muntha falls on a natal planet of importance." },

  // ── Chapter 4: Ithasala Yoga ──────────────────────────────────────────────
  { chapter: 4, verse: 1, content: "Ithasala is the primary Tajaka Yoga and the most important of the five principal combinations. Ithasala occurs when a faster-moving planet is applying by degree towards a slower-moving planet, with both within the sum of their deeptamsas (orbs). The faster planet must have a higher degree than the slower planet for a direct Ithasala." },
  { chapter: 4, verse: 2, content: "The rule of Ithasala: planet A is faster and at degree X; planet B is slower and at degree Y. If X > Y and X - Y is less than the combined orb of the two planets, and both are in the same sign or adjacent signs forming an aspect, then Ithasala exists from A to B. The matter signified by both planets and their houses will come to fruition in the annual period." },
  { chapter: 4, verse: 3, content: "The strength of Ithasala is inversely proportional to the orb: a tight Ithasala within 1° delivers its result quickly and completely; a wide Ithasala near the edge of the orb delivers the result slowly or partially. Neelakantta recommends focusing on Ithasalas within half the combined orb for assured results." },
  { chapter: 4, verse: 4, content: "The nature of the matter signified by Ithasala is determined by: (1) the two planets involved and their natural significations; (2) the houses they occupy in the annual chart; (3) the houses they rule in the annual chart; (4) the house in whose sign the Ithasala is forming. All four factors blend to describe the specific matter coming to fruition." },
  { chapter: 4, verse: 5, content: "Ithasala between Venus and the 7H lord in the annual chart signals marriage or significant partnership events during the year. Ithasala between Jupiter and the 5H lord signals birth of a child or completion of an important creative project. Ithasala between the Sun and the 10H lord signals career advancement or recognition from authority." },
  { chapter: 4, verse: 6, content: "Ithasala between malefics brings the signified matter to fruition through difficulty, conflict, or forced circumstances. A Mars-Saturn Ithasala in the annual chart can signify a forced career change, surgery, or property dispute — the matter completes but through adversity. The benefic or malefic nature of the completing planets determines the experiential quality." },
  { chapter: 4, verse: 7, content: "The Ithasala Yoga is only fully operative when both planets are free from combustion, retrograde motion, and debilitation in the annual chart. A retrograde planet in an Ithasala may not deliver its promise — the matter begins but may reverse. A combust planet in an Ithasala is weakened and delivers the matter imperfectly or partially." },
  { chapter: 4, verse: 8, content: "Neelakantta identifies three grades of Ithasala quality: (1) both planets in good dignity (own sign, exaltation, Moolatrikona, or friendly sign) — complete and excellent delivery; (2) one in good dignity, one neutral — partial delivery with some obstacles; (3) both in neutral or enemy signs — delivery is minimal, delayed, or disappointing." },
  { chapter: 4, verse: 9, content: "Ithasala from the Lagna lord to the 10H lord in the annual chart is among the most important career combinations. The native's personal initiative (Lagna lord) is applying toward career achievement (10H lord); the year brings professional advancement through direct effort. The tighter the orb, the more decisive the career movement." },
  { chapter: 4, verse: 10, content: "Ithasala from the Lagna lord to the 7H lord in the annual chart signals a year when personal initiative drives partnership events: marriage decision, business partnership formation, or significant 1:1 negotiation. The Lagna lord drives the meeting; the 7H lord represents the partner or the contractual outcome." },
  { chapter: 4, verse: 11, content: "Double Ithasala: when planet A is in Ithasala with planet B, and planet B is simultaneously in Ithasala with planet C, the matter passes through a chain of activation. The final result is coloured by all three planets' significations. Neelakantta calls this Dwi-Ithasala — rarely seen but highly powerful when present." },
  { chapter: 4, verse: 12, content: "Ithasala involving the Varshesha amplifies the annual result. When the Varshesha is one of the two Ithasala planets, the matter coming to fruition is directly supported by the year lord, making completion more assured. The Varshesha lending its strength to an Ithasala is one of the most reliable timing signals in Tajaka." },
  { chapter: 4, verse: 13, content: "The timing of Ithasala delivery within the annual period: Ithasala between fast planets (Moon, Mercury) activates events in the first third of the year. Ithasala involving medium-speed planets (Sun, Mars, Venus) activates in the middle third. Ithasala involving slow planets (Jupiter, Saturn) activates in the final third or near year-end." },
  { chapter: 4, verse: 14, content: "Ithasala in Dwiswabhava (dual) signs (Gemini, Virgo, Sagittarius, Pisces) delivers its results in two phases: an initial partial manifestation early in the year, followed by full completion later. The dual sign splits the delivery. Ithasala in fixed signs (Taurus, Leo, Scorpio, Aquarius) delivers its result firmly but slowly." },
  { chapter: 4, verse: 15, content: "Ithasala in movable signs (Aries, Cancer, Libra, Capricorn) delivers its result quickly, often in the first quarter of the annual period. Movable signs accelerate all Tajaka yogas. The type of sign occupied by the completing Ithasala determines the temporal distribution of the year's events." },
  { chapter: 4, verse: 16, content: "A planet in Ithasala with the annual chart's Lagna degree itself (i.e., applying towards the exact degree of the Varsha Lagna) indicates a personal, identity-level event during the year. The native's health, appearance, or self-image is directly affected by the completing planet's nature." },
  { chapter: 4, verse: 17, content: "Neelakantta gives the rule of interrupted Ithasala: if a third planet intervenes between the two Ithasala planets — i.e., the third planet is between their degrees in the same or adjacent sign and within orb of both — the Ithasala is blocked or transferred. This third-planet interception creates the Nakta or Dutthottha Yogas." },
  { chapter: 4, verse: 18, content: "Ithasala's practical application in chart reading: first identify all applying aspects (degree-based) between planets within their combined orbs; second, note which planets are the applying (faster) and receiving (slower) bodies; third, map the houses ruled and occupied by each planet; fourth, synthesise the matter signified and assess quality by dignity." },
  { chapter: 4, verse: 19, content: "Ithasala involving the 8H and 8H lord in the annual chart — even when benefics are involved — brings the matter to fruition through a transformative or crisis-level event. Jupiter in Ithasala with the 8H lord may bring inheritance; Venus in Ithasala with the 8H lord may bring a significant relationship transformed by crisis." },
  { chapter: 4, verse: 20, content: "The most auspicious Ithasala in any annual chart: Jupiter (applying) to Venus (receiving) in the annual chart's 5H or 9H, with both planets in friendly dignity. This configuration brings creative fulfilment, children, spiritual advancement, and material prosperity simultaneously — the year's events are unambiguously blessed." },
  { chapter: 4, verse: 21, content: "Neelakantta's summary of Ithasala: it is the heart of Tajaka analysis. Every annual chart must be examined for its Ithasalas before any other judgment is made. The Ithasalas present in the annual chart are the year's active contracts — each one representing a matter that will manifest in the annual period." },

  // ── Chapter 5: Ishrafa Yoga ───────────────────────────────────────────────
  { chapter: 5, verse: 1, content: "Ishrafa is the Tajaka Yoga of separation. It occurs when a faster-moving planet has already passed beyond a slower planet (the faster planet is at a lower degree than the slower) but is still within the combined orb of the two planets. The matter signified has already come to its peak and is now moving into its declining phase." },
  { chapter: 5, verse: 2, content: "Ishrafa indicates that the matter signified by the two planets reached its maximum expression before the annual period began or in its very early phase. The native may still experience the echo of this completion, but fresh pursuit of the matter will yield diminishing returns. The lesson of Ishrafa is to consolidate and transition, not to pursue what has passed." },
  { chapter: 5, verse: 3, content: "Ishrafa between the Lagna lord and the 7H lord: the native has already reached a turning point in a partnership. A relationship that peaked before this annual period is now separating or declining. The year is better spent acknowledging what has passed than forcing a revival. New partnerships are favoured over reviving old ones." },
  { chapter: 5, verse: 4, content: "Ishrafa between the 10H lord and the Sun in the annual chart: a career peak has passed. The native experienced their maximum professional recognition in the prior period; this annual period is one of consolidation, internal restructuring, or a quiet transition to the next professional phase. Forcing advancement against this Ishrafa brings frustration." },
  { chapter: 5, verse: 5, content: "Ishrafa between benefics is milder — the separation is of a pleasant matter, but the matter's time has passed. Ishrafa between malefics indicates the passing of a crisis — the hardest point is behind the native and the annual period involves recovery and rebuilding after the storm has passed." },
  { chapter: 5, verse: 6, content: "The timing of Ishrafa within the annual period: Ishrafa's effects are strongest at the very start of the annual period and diminish as the year progresses. By the year's midpoint, the Ishrafa matter is resolved or accepted. New Ithasalas forming later in the year carry more weight for the second half's events." },
  { chapter: 5, verse: 7, content: "Ishrafa from the Varshesha to another planet: even the year lord's signature matter has peaked before the annual period begins. The Varshesha cannot fully deliver its promise — there is a fundamental incompleteness to the year's dominant theme. The native must accept a year of maintenance rather than breakthrough." },
  { chapter: 5, verse: 8, content: "Neelakantta's practical guidance for Ishrafa years: the native should review and consolidate prior accomplishments, clear debts and obligations from the prior period, and prepare the ground for future Ithasalas. Ishrafa years are excellent for inner work, completion of unfinished business, and course correction." },
  { chapter: 5, verse: 9, content: "Ishrafa in the annual 5H: creative projects or children events that were begun in the prior annual period are now concluding. The native may complete a creative work they started previously. A child born in the prior year is now integrated into the family. The creative impulse itself is transitioning to a new direction." },
  { chapter: 5, verse: 10, content: "An annual chart with many Ishrafa Yogas and few Ithasala Yogas is a year of consolidation and endings. Neelakantta calls such years 'Samapti Varsha' — completion years. They are less externally dramatic than Ithasala-dominated years but carry their own essential function in the native's life arc." },
  { chapter: 5, verse: 11, content: "Ishrafa can coexist with Ithasala in the same annual chart. One planetary pair may be in Ishrafa (a matter concluding) while another pair is in Ithasala (a new matter coming to fruition). Reading the full palette of Ithasala and Ishrafa Yogas together gives the annual chart its complete narrative of endings and beginnings." },
  { chapter: 5, verse: 12, content: "Neelakantta distinguishes between near Ishrafa (within 1° of separation) and wide Ishrafa (within 3–5° of separation). Near Ishrafa indicates a very recent completion — the matter concluded just before the annual period. Wide Ishrafa indicates a completion from the prior cycle that the native is still processing emotionally or practically." },
  { chapter: 5, verse: 13, content: "The house occupied by the Ishrafa separation point reveals where the completion is occurring. Ishrafa in the 4H of the annual chart: a home-related matter (residence, family, mother) has completed its cycle and is now in natural decline. Ishrafa in the 11H: a network of friendships or financial gains has peaked and is diminishing." },
  { chapter: 5, verse: 14, content: "Summary: Ishrafa is not inherently malefic — it is the natural completion of a cycle. Fear of Ishrafa years misunderstands the system. Every Ishrafa clears the field for a subsequent Ithasala. The skilled Tajaka practitioner reads Ishrafa as an invitation to completion, consolidation, and conscious transition." },

  // ── Chapter 6: Nakta Yoga ─────────────────────────────────────────────────
  { chapter: 6, verse: 1, content: "Nakta Yoga is the Tajaka Yoga of indirect transfer. It arises when planet A is in Ishrafa from planet B (the direct connection has passed), but a third planet C is in Ithasala with both A and B simultaneously. Planet C acts as an intermediary, transferring A's separated influence to B and bringing the matter to fruition through an indirect channel." },
  { chapter: 6, verse: 2, content: "The identifying condition of Nakta: (1) A and B are in Ishrafa — their direct Ithasala has separated; (2) C is applying toward both A and B — C is between A and B in degree and within orb of both; (3) C's involvement transfers the matter that would have been blocked by the Ishrafa into a new channel of manifestation." },
  { chapter: 6, verse: 3, content: "Nakta Yoga signifies that the matter in question will arrive through an intermediary: a third party, an unexpected agent, an indirect route, or a facilitator. The native cannot obtain the result through direct effort alone in the annual period; success requires working through channels, networks, and helpers." },
  { chapter: 6, verse: 4, content: "The nature of the intermediary planet C in Nakta determines the nature of the indirect channel. Mercury as C indicates the intermediary is communicative — a letter, a conversation, a broker, or a communicator facilitates the result. Jupiter as C indicates the intermediary is a teacher, priest, or wise counsellor. Venus as C indicates the intermediary is a friend, artist, or woman." },
  { chapter: 6, verse: 5, content: "Saturn as the Nakta intermediary (planet C) indicates the indirect channel involves delay, bureaucracy, or an older person. Mars as C indicates the channel involves a competitor, soldier, or someone who uses force or urgency. Moon as C indicates the channel involves a woman, public figure, or emotional appeal." },
  { chapter: 6, verse: 6, content: "Nakta Yoga in the annual 10H: the career advancement of the annual period will come through a third party — a referral, recommendation, or sponsorship rather than direct application. The native who tries to obtain career results through direct effort alone will be frustrated; working through connections is the operative mechanism." },
  { chapter: 6, verse: 7, content: "Nakta in the annual 7H: partnership or marriage events of the year will be facilitated by an intermediary — a matchmaker, a mutual friend, a colleague who introduces the parties. Direct approaches to potential partners are less effective than working through established networks of trust." },
  { chapter: 6, verse: 8, content: "Nakta involving the Varshesha as planet C (the intermediary): the year lord itself becomes the channel through which a blocked matter finds resolution. The Varshesha's significations infuse the transferred matter — a Jupiter Varshesha as Nakta intermediary brings the result through dharmic channels; a Venus Varshesha brings it through pleasurable connections." },
  { chapter: 6, verse: 9, content: "The strength of Nakta Yoga depends on the strength of the intermediary planet C. A strong, well-dignified C in an angular house delivers the transferred matter reliably. A weak or afflicted C in a dusthana makes the indirect channel unreliable — the intermediary may fail, delay, or deliver only partial results." },
  { chapter: 6, verse: 10, content: "Neelakantta's practical guidance for Nakta years: the native should actively cultivate networks and relationships rather than relying on individual effort. Collaboration, coalition-building, and working through established channels are the year's strategic imperatives. Solo efforts are frustrated; team efforts succeed." },
  { chapter: 6, verse: 11, content: "Nakta involving malefics as the intermediary can bring the result through adversarial or difficult channels: a lawsuit that is unexpectedly resolved, a competitor who inadvertently creates an opportunity, or a bureaucratic obstacle that forces a creative solution. The result still arrives, but through an uncomfortable route." },
  { chapter: 6, verse: 12, content: "Nakta Yoga is specific to the Tajaka system and has no direct parallel in Parashari or Jaimini timing methods. It represents the Tajaka system's recognition that human life often works through indirection — the most important outcomes of any year frequently arrive through channels the native did not expect or directly control." },
  { chapter: 6, verse: 13, content: "Summary of Nakta: when a direct connection (Ithasala) has passed but a third planet bridges the gap, the matter is not lost but redirected through an intermediary. The key practical insight is that the native should look for and cultivate the intermediary (the planet C's signification) to unlock the year's promise." },

  // ── Chapter 7: Kambula Yoga ───────────────────────────────────────────────
  { chapter: 7, verse: 1, content: "Kambula Yoga is the Tajaka Yoga of double benefic protection. It arises when two benefic planets (Jupiter, Venus, Mercury when well-placed, or Moon when not afflicted) are in angular relationship to each other in the Varsha Kundali — either in conjunction, opposition, square, trine, or sextile — and at least one of the two benefics is in its own sign or exaltation." },
  { chapter: 7, verse: 2, content: "Kambula's effect is general protective beneficence over the entire annual period. The year proceeds smoothly; the native experiences balance between spiritual and material pursuits; creative achievements come with relative ease; relationships are harmonious; and the overall experiential quality of the year is positive and nourishing." },
  { chapter: 7, verse: 3, content: "Kambula between Jupiter and Venus is the most powerful form of this yoga. Jupiter brings wisdom, expansion, and dharmic alignment; Venus brings beauty, pleasure, and relationship harmony. Their angular relationship in the annual chart creates a dual benefic umbrella that protects the native across most domains of life for the year." },
  { chapter: 7, verse: 4, content: "Kambula between Jupiter and Mercury brings a year of intellectual achievement, communication success, and educational accomplishment. The native's mental faculties are sharpened; writing, teaching, or scholarly work bears fruit; contracts and negotiations are concluded favourably. Business and trade flourish under Jupiter-Mercury Kambula." },
  { chapter: 7, verse: 5, content: "Kambula between Venus and Mercury in the annual chart favours arts, crafts, trade, and all activities combining beauty with intelligence. The year is excellent for creative writing, artistic performance, relationship deepening, and commercial activities. Social life is particularly active and rewarding." },
  { chapter: 7, verse: 6, content: "Kambula involving the Moon requires that the Moon be bright (more than 7 tithis from the Sun), unafflicted by Rahu or Saturn, and in a friendly or own sign. A bright, well-placed Moon in angular relationship to Jupiter or Venus creates Kambula. A dark or afflicted Moon in this configuration is not counted as Kambula." },
  { chapter: 7, verse: 7, content: "Kambula in the annual 1H and 7H axis (two benefics in opposition across the Lagna): the native and their partner are both supported by benefic energy. The year favours marriage, business partnership, and all 1:1 relationships. The opposition axis means the native's self-interest and partner's interest are balanced." },
  { chapter: 7, verse: 8, content: "Kambula in the annual 4H and 10H axis: domestic peace and professional achievement are simultaneously activated. The native can advance in career without sacrificing domestic harmony — the two usually competing domains of life support each other in a Kambula year on the 4-10 axis." },
  { chapter: 7, verse: 9, content: "Kambula involving the Varshesha elevates the annual chart's quality still further. When the Varshesha is one of the two Kambula benefics, the year lord's protective energy is doubled by its angular relationship to another benefic. Such years are among the best in any native's life." },
  { chapter: 7, verse: 10, content: "Kambula is weakened by malefic aspects to the involved benefics. If Saturn aspects one of the Kambula benefics, it slows the benefic's delivery. If Mars aspects one, it adds friction or conflict to what would otherwise be smooth. Rahu or Ketu conjunct one of the Kambula benefics distorts or complicates the benefic's expression." },
  { chapter: 7, verse: 11, content: "Neelakantta's summary of Kambula: it is the Tajaka yoga of grace — the annual period blessed by the combined presence of two benefics in angular relationship. Kambula years are to be welcomed and actively utilised for creative, relational, and spiritual pursuits. They do not guarantee absence of difficulty but ensure that the year's overall arc is positive." },

  // ── Chapter 8: Dutthottha Yoga ────────────────────────────────────────────
  { chapter: 8, verse: 1, content: "Dutthottha Yoga is the Tajaka Yoga of assisted manifestation. It occurs when a planet A is in Ishrafa from planet B (their Ithasala has separated), but a third planet C is in Ithasala with planet B directly and also aspects or conjoins planet A. Planet C assists A's matter to reach B by directly carrying A's energy forward to B." },
  { chapter: 8, verse: 2, content: "The distinction between Dutthottha and Nakta: in Nakta, the intermediary C is between A and B in degree. In Dutthottha, the intermediary C is in Ithasala with B and also aspects A from a different position — C is not between A and B but alongside A, carrying A's influence to B from its own position." },
  { chapter: 8, verse: 3, content: "Dutthottha signifies that a matter blocked by Ishrafa is rescued by a powerful ally or agent who independently connects both the originating planet and the receiving planet. The result arrives through an active advocate or champion rather than through a passive intermediary (as in Nakta)." },
  { chapter: 8, verse: 4, content: "Dutthottha involving Jupiter as planet C: a guru, wise elder, or spiritual authority advocates for the native's matter and ensures its completion. The annual period brings someone of wisdom and authority who bridges the gap between what the native intended and what actually manifests. Dharmic intervention rescues a blocked matter." },
  { chapter: 8, verse: 5, content: "Dutthottha involving Venus as C: a partner, artist, or diplomatic figure actively champions the native's cause and brings the matter to completion. The advocate is charming, aesthetically aware, and works through relationship channels. The result arrives through a pleasant and pleasurable intermediary." },
  { chapter: 8, verse: 6, content: "Neelakantta clarifies that both Nakta and Dutthottha require precise degree calculation to identify the intermediary planet. Casual observation of sign-based aspects is insufficient — the specific degrees of all three planets must be calculated and their orbs verified. These yogas require precision that lesser Tajaka practitioners overlook." },
  { chapter: 8, verse: 7, content: "Dutthottha in the annual 10H involving the career lord: a blocked career advancement is rescued by a powerful ally or patron who intervenes on the native's behalf. The year's career outcome comes not from the native's solo effort but from the active advocacy of someone placed to influence the decision-makers." },
  { chapter: 8, verse: 8, content: "The practical guidance of Dutthottha: the native should identify who in their environment is in a position to actively champion their cause — this person corresponds to the intermediary planet C in the yoga. Cultivating this person's goodwill and clearly communicating the native's needs to them is the year's strategic imperative." },
  { chapter: 8, verse: 9, content: "Summary of the five Tajaka Yogas: Ithasala (direct application — matter comes on its own momentum), Ishrafa (direct separation — matter has passed), Nakta (passive intermediary — matter arrives through an unexpected channel), Kambula (double benefic protection — overall year blessed), Dutthottha (active advocate — a champion rescues a blocked matter). These five cover all possible configurations of applying and separating aspects in the annual chart." },

  // ── Chapter 9: The Sixteen Sahamas (Arabic Parts) ────────────────────────
  { chapter: 9, verse: 1, content: "The Sahamas (Arabic Parts) are sensitive points in the Varsha Kundali calculated as Lagna + Planet A - Planet B, using the Varsha Kundali's Lagna rather than the natal Lagna. The sixteen standard Sahamas each govern a specific domain of annual life. Their placement and aspects reveal the year's promise in each domain." },
  { chapter: 9, verse: 2, content: "Punya Sahama (Part of Fortune): Lagna + Moon - Sun (day birth) or Lagna + Sun - Moon (night birth). The primary benefic Sahama, it governs the native's general annual fortune and wellbeing. Punya Sahama in an angle of the Varsha Kundali and aspected by a benefic gives an auspicious year of general fortune." },
  { chapter: 9, verse: 3, content: "Vidya Sahama (Part of Knowledge): Lagna + Mercury - Jupiter. Governs learning, intellectual achievement, and educational attainments in the annual period. Vidya Sahama strong and in a good house with Mercury aspecting brings certification, completion of studies, or intellectual recognition in the year." },
  { chapter: 9, verse: 4, content: "Yasha Sahama (Part of Fame): Lagna + Jupiter - Sun. Governs reputation, public recognition, and social standing in the annual period. Yasha Sahama in the 10H or 1H of the annual chart and aspected by Jupiter gives a year of public recognition and enhanced reputation." },
  { chapter: 9, verse: 5, content: "Mitra Sahama (Part of Friendship): Lagna + Jupiter - Moon. Governs friendships, networks, and social alliances in the annual period. Mitra Sahama in the 11H or aspected by Venus and Jupiter gives a year of strong social connections and supportive friendships." },
  { chapter: 9, verse: 6, content: "Mahadasha Sahama (Part of Prosperity): Lagna + Venus - Jupiter. Governs material prosperity and comfort in the annual period. Mahadasha Sahama in the 2H or 11H of the annual chart and aspected by Venus gives a year of material abundance and financial accumulation." },
  { chapter: 9, verse: 7, content: "Paradesa Sahama (Part of Foreign Lands): Lagna + Saturn - Sun. Governs travel, foreign residence, and dealings with foreign cultures in the annual period. Paradesa Sahama strong and in the 12H or 9H of the annual chart with Saturn's aspect can indicate foreign residence or significant international engagement in the year." },
  { chapter: 9, verse: 8, content: "Kali Sahama (Part of Strife): Lagna + Mars - Saturn. Governs conflicts, disputes, enemies, and struggles in the annual period. Kali Sahama in the 6H of the annual chart and aspected by Mars intensifies conflicts and enemy encounters in the year. Saturn aspecting Kali Sahama makes the conflicts slow and grinding." },
  { chapter: 9, verse: 9, content: "Dara Sahama (Part of Spouse): Lagna + Venus - Saturn (some schools: Lagna + 7H lord - Venus). Governs marriage and partnerships in the annual period. Dara Sahama in an angle of the annual chart and aspected by Venus or Jupiter activates marriage events — either a new partnership or significant deepening of an existing one." },
  { chapter: 9, verse: 10, content: "Putra Sahama (Part of Children): Lagna + Jupiter - Saturn (variations exist). Governs children, creativity, and 5H matters in the annual period. Putra Sahama in the 5H of the annual chart and aspected by Jupiter indicates a year when children events (birth, child's major milestone, or conception) become prominent." },
  { chapter: 9, verse: 11, content: "Karma Sahama (Part of Work and Career): Lagna + Mars - Sun. Governs professional activities and career in the annual period. Karma Sahama in the 10H of the annual chart and aspected by the Sun or Mars brings career advancement, new responsibilities, or entrepreneurial success in the year." },
  { chapter: 9, verse: 12, content: "Roga Sahama (Part of Disease): Lagna + Saturn - Moon. Governs health challenges in the annual period. Roga Sahama in the 6H or 8H of the annual chart and aspected by Saturn or Mars with the Moon afflicted indicates a year when health requires careful attention. Medical interventions or chronic conditions flare during such a configuration." },
  { chapter: 9, verse: 13, content: "Paka Sahama (Part of Digestion/Vitality): Lagna + Moon - Saturn (variant formula). Governs the physical constitution and vitality in the annual period. Paka Sahama afflicted in the annual chart (aspected by malefics, placed in dusthana) indicates digestive problems and reduced physical vitality that require dietary discipline and medical attention." },
  { chapter: 9, verse: 14, content: "Kara Sahama (Part of Action): Lagna + Sun - Saturn. Governs initiative, self-direction, and purposeful action in the annual period. Kara Sahama strong in the 1H or 10H with Sun and Mars aspecting gives a year when the native's direct initiative and bold action bring results. Afflicted Kara Sahama makes initiating actions frustrating or counterproductive." },
  { chapter: 9, verse: 15, content: "Aasa Sahama (Part of Hope and Desire): Lagna + Moon - Jupiter. Governs wishes, desires, and aspirations in the annual period. Aasa Sahama in the 11H of the annual chart (the house of gains and wishes) and aspected by Jupiter gives a year when the native's heartfelt wishes materialise. Afflicted Aasa Sahama brings frustrated hopes despite sincere effort." },
  { chapter: 9, verse: 16, content: "Vivaha Sahama (Part of Marriage): a secondary marriage-signifying Sahama computed from the relationship between Venus, Moon, and the 7H. Vivaha Sahama is especially consulted in Tajaka readings when the native is approaching marriageable age or when significant partnership events are anticipated in the annual period." },
  { chapter: 9, verse: 17, content: "The method of Sahama analysis: (1) calculate the Sahama longitude; (2) place the Sahama in its house in the annual chart; (3) identify which planets aspect the Sahama and whether they are benefic or malefic; (4) identify the Sahama's lord (the ruler of the sign the Sahama falls in) and assess that lord's condition; (5) synthesise the annual domain's promise from these four factors." },
  { chapter: 9, verse: 18, content: "A Sahama in an angular house of the annual chart (1H, 4H, 7H, 10H) is empowered to deliver its domain's results. A Sahama in a trine (5H, 9H) delivers its results with grace and fortune. A Sahama in a dusthana (6H, 8H, 12H) delivers its results through difficulty or withholds them entirely, depending on aspects." },
  { chapter: 9, verse: 19, content: "Neelakantta's priority sequence for Sahama analysis: (1) Punya Sahama — general fortune; (2) Karma Sahama — career; (3) Dara Sahama — marriage; (4) Putra Sahama — children; (5) Roga Sahama — health. These five cover the five primary life domains and must be assessed in every annual chart delineation." },
  { chapter: 9, verse: 20, content: "Summary of the Sahamas: they are the annual chart's domain-specific sensors. Each Sahama measures the annual promise in one specific area of life. Together, the sixteen Sahamas provide a complete map of the year's potential across all major life domains. No comprehensive Tajaka reading is complete without the Sahama analysis." },

  // ── Chapter 10: The Annual Lagna and Navamsha ─────────────────────────────
  { chapter: 10, verse: 1, content: "The Varsha Lagna (annual ascendant) is calculated for the exact moment the Sun returns to its natal longitude, using the native's current place of residence. The Lagna's sign, its degree, the Lagna lord, and planets placed in or aspecting the Lagna house are the annual chart's primary structural foundation." },
  { chapter: 10, verse: 2, content: "The annual Navamsha (D9) derived from the Varsha Kundali provides a deeper layer of annual analysis. When the annual Navamsha Lagna is the same sign as the natal Navamsha Lagna, the year has especially strong personal significance. Planets in the annual Navamsha in the same position as natal Navamsha planets receive double activation." },
  { chapter: 10, verse: 3, content: "Planets placed in the annual Lagna house of the Varsha Kundali directly affect the native's physical health, personal identity, and self-expression during the year. A benefic in the annual Lagna (Jupiter, Venus, or strong Mercury) gives vitality, personal magnetism, and successful self-presentation. A malefic in the annual Lagna (Saturn, Mars, Rahu) brings physical challenges or conflict to the self." },
  { chapter: 10, verse: 4, content: "The annual Lagna lord's placement and condition determines the native's personal agency and effectiveness during the year. Annual Lagna lord in an angle: the native is effective, active, and able to pursue their goals directly. Annual Lagna lord in a dusthana: the native faces obstacles to personal initiative and may feel blocked or frustrated in self-directed efforts." },
  { chapter: 10, verse: 5, content: "The degree of the annual Lagna activates specific nakshatras and nakshatra padas. When the annual Lagna degree falls in the same nakshatra as a natal planet, that natal planet's themes are especially alive during the year. When the annual Lagna falls in the native's natal birth nakshatra (Janma nakshatra), the year is personally pivotal." },
  { chapter: 10, verse: 6, content: "The Hora Lagna (HL) is calculated for the annual chart by taking the time elapsed since sunrise at the solar return moment and converting to ghatis (1 ghati = 24 minutes). Each sign lasts 1 hora (half a rasi hour = 30 minutes). The HL and its lord indicate the financial dimension of the annual period more specifically than the general Lagna." },
  { chapter: 10, verse: 7, content: "The Ghatika Lagna (GL) is calculated from the running ghati at the solar return moment — each ghati (24 minutes of clock time) advances the GL by one sign. The GL and its lord indicate the power, status, and political dimension of the annual period. The GL lord strong in the annual chart brings elevated status and authority in the year." },
  { chapter: 10, verse: 8, content: "The relationship between the three annual Lagnas (Varsha Lagna, Hora Lagna, Ghatika Lagna) creates a three-dimensional view of the year: the Varsha Lagna shows the native's overall self-expression; the Hora Lagna shows financial potential; the Ghatika Lagna shows power and authority. When all three are in harmony, the year is coherent and its energies well-directed." },
  { chapter: 10, verse: 9, content: "The annual Vargottama condition: when a planet occupies the same sign in both the annual D1 and the annual Navamsha, it is Vargottama in the annual chart. Vargottama planets in the annual chart deliver their results with unusual clarity and force. The Vargottama condition in the annual chart amplifies whatever the planet signifies for the year." },
  { chapter: 10, verse: 10, content: "When the annual Lagna itself is Vargottama (same sign in annual D1 and annual Navamsha), the year has a quality of consistent, unfragmented self-expression. The native knows what they want in this annual period and pursues it coherently. Vargottama Lagna years are remembered as particularly clear and decisive years." },
  { chapter: 10, verse: 11, content: "The annual chart's Navamsha placement of the Varshesha provides additional detail about the year lord's quality. Varshesha in its own Navamsha sign (own sign or Moolatrikona in the annual Navamsha): the year lord is doubly empowered and delivers its maximum promise. Varshesha debilitated in the annual Navamsha: even if the Varshesha is well-placed in the annual D1, its delivery is compromised." },
  { chapter: 10, verse: 12, content: "Neelakantta gives special emphasis to the annual 10H analysis: the annual 10H lord, its placement, strength, aspects, and the planets placed in the annual 10H collectively determine the year's career events. This analysis mirrors natal 10H analysis but applies to the one-year window of the Varsha Kundali." },
  { chapter: 10, verse: 13, content: "Summary of annual Lagna analysis: the Varsha Lagna is the annual chart's anchor. It defines the year's self-referential centre, from which all house significations radiate. Its lord, its aspecting planets, and its Navamsha placement all contribute to the year's fundamental character and the native's capacity for effective self-direction in the annual period." },

  // ── Chapter 11: Annual Dashas (Mudda Dasha) ───────────────────────────────
  { chapter: 11, verse: 1, content: "Tajaka employs an annual Dasha system called Mudda Dasha (also called Varsha Dasha or annual Narayana Dasha in some traditions). The Mudda Dasha distributes the 365-day annual period among the seven planets according to their specific Tajaka period lengths, starting from the annual Lagna lord or the Varshesha." },
  { chapter: 11, verse: 2, content: "The Mudda Dasha periods for each planet in the annual 365-day cycle: Sun = 11 days, Moon = 31 days, Mars = 21 days, Mercury = 17 days, Jupiter = 45 days, Venus = 27 days, Saturn = 116 days. Together these sum to 268 days. The remaining 97 days are distributed based on the starting point and any overlapping Antardasha periods." },
  { chapter: 11, verse: 3, content: "The sequence of Mudda Dasha begins from the Varshesha and proceeds in the weekday order (Sun, Moon, Mars, Mercury, Jupiter, Venus, Saturn). The Dasha of the Varshesha runs first for the duration appropriate to that planet; the subsequent Dashas follow in weekday order until the annual period is exhausted." },
  { chapter: 11, verse: 4, content: "During a planet's Mudda Dasha period within the annual cycle, that planet's significations and house lordships in the Varsha Kundali are activated. If the Mudda Dasha planet is well-placed in the annual chart and free from affliction, its period brings positive results in its domain. If afflicted or badly placed, its period brings challenges." },
  { chapter: 11, verse: 5, content: "Mudda Antardasha (sub-period within each Mudda Dasha) further divides each planet's annual Dasha period proportionally. The Antardasha lord's condition in the annual chart determines whether each sub-period within the annual cycle is auspicious or challenging for the specific significations of that sub-period." },
  { chapter: 11, verse: 6, content: "The intersection of Mudda Dasha with Ithasala Yoga is the most precise timing tool in Tajaka. When the Mudda Dasha lord is simultaneously in Ithasala with another planet in the annual chart, the matter signified by that Ithasala manifests specifically during the Mudda Dasha period — not at the year's beginning or end but during this specific dasha window." },
  { chapter: 11, verse: 7, content: "Neelakantta emphasises that Mudda Dasha provides the 'when' of the annual period — the sequence of activated domains. Combined with the 'what' of Ithasala/Ishrafa analysis and the 'where' of Sahama analysis, the three-layer framework gives a comprehensive annual delineation with both thematic content and temporal precision." },
  { chapter: 11, verse: 8, content: "The Saturn Mudda Dasha, being the longest at 116 days, dominates approximately one-third of any annual period. During the Saturn Mudda period, discipline, delayed gratification, service obligations, and karmic themes are emphasised. This is the annual period's 'long work' phase where patient effort rather than quick results is the operative mode." },
  { chapter: 11, verse: 9, content: "The Moon Mudda Dasha (31 days) is the annual period's most emotionally active phase. Domestic matters, mother, public reception, and emotional themes are heightened. The Moon's Mudda phase in any annual cycle is typically the most personally felt and the most emotionally resonant sub-period of the year." },
  { chapter: 11, verse: 10, content: "Summary of Mudda Dasha: it is the temporal skeleton of the annual period, distributing the year's promise across a sequence of activated planetary themes. Each Mudda Dasha lord's period corresponds to that planet's contribution to the annual period's events. Together with Ithasala analysis and Sahama placement, Mudda Dasha completes the Tajaka analytical framework." },

  // ── Chapter 12: Strength Assessment in Tajaka ─────────────────────────────
  { chapter: 12, verse: 1, content: "The Harsha Bala (annual strength) system of Tajaka assesses each planet's effectiveness in the annual chart. Unlike the natal Shadbala system which requires extensive calculation, Harsha Bala uses five dignity levels: own sign (3 points), exaltation (2 points), Moolatrikona (2 points), friendly sign (1 point), neutral sign (0.5 points), enemy sign or debilitation (0 points)." },
  { chapter: 12, verse: 2, content: "Angular placement adds bonus Harsha Bala: a planet in the 1H receives 1.5× its dignity score; in the 10H receives 1.5×; in the 4H or 7H receives 1.25×. A planet in a trine (5H, 9H) receives 1× its dignity score. A planet in a dusthana (6H, 8H, 12H) receives only 0.5× its dignity score, regardless of its dignity level." },
  { chapter: 12, verse: 3, content: "Panchadhatu strength: five additional factors add or subtract from Harsha Bala: (1) retrograde adds 1 point (retrograde = strong but unpredictable); (2) own nakshatra adds 0.5; (3) Vargottama in annual Navamsha adds 0.5; (4) aspected by natural benefics adds 0.5 per aspecting benefic; (5) aspected by natural malefics subtracts 0.5 per aspecting malefic." },
  { chapter: 12, verse: 4, content: "Tajaka does not use the Parashari Sthana Bala, Kala Bala, Cheshta Bala, or Drik Bala sub-systems. The Harsha Bala is a simplified but precise annual-specific strength metric. For Tajaka purposes, Harsha Bala is sufficient — the natal Shadbala provides the background strength; Harsha Bala provides the annual-specific strength." },
  { chapter: 12, verse: 5, content: "A planet with Harsha Bala above 2.5 is considered strong in the annual chart and can deliver its significations with minimal obstruction. A planet with Harsha Bala between 1.0 and 2.5 is moderate — results come with effort. A planet with Harsha Bala below 1.0 is weak and struggles to deliver its promises in the annual period." },
  { chapter: 12, verse: 6, content: "Retrograde planets in the annual chart: they have elevated Harsha Bala but deliver their results in an unusual, reversed, or delayed manner. A retrograde Jupiter in the annual chart may delay financial expansion but ultimately delivers it from an unexpected direction. The retrograde's promise is not cancelled but redirected." },
  { chapter: 12, verse: 7, content: "Combustion in the annual chart: a planet within 6° of the Sun (adapting Parashari combustion orbs to the annual chart) has its Harsha Bala reduced by half. Severe combustion (within 1° of the Sun) effectively eliminates the planet's capacity to deliver its annual promise independently. The Sun absorbs the combust planet's significations into the native's ego expression." },
  { chapter: 12, verse: 8, content: "The Tajaka strength of the Varshesha specifically is assessed using Harsha Bala combined with its Ithasala pattern. A Varshesha with high Harsha Bala but in Ishrafa from most other planets in the annual chart delivers the year's theme incompletely despite its personal strength. Strength must be paired with active Ithasala connections to fully manifest." },
  { chapter: 12, verse: 9, content: "Neelakantta's summary on strength: in the Tajaka system, strength (Harsha Bala) is necessary but not sufficient. A planet must be strong AND in active Ithasala connection with relevant planets to deliver its annual promise. A strong isolated planet (no Ithasalas, no aspects from others) has potential that does not manifest in the annual period." },
  { chapter: 12, verse: 10, content: "The relative strength comparison between annual chart planets determines the Varshesha, the effectiveness of Nakta/Dutthottha intermediaries, and the dominance hierarchy among competing house lords. Tajaka judgment requires knowing each planet's Harsha Bala number so that relative prioritisation is possible when multiple factors conflict." },

  // ── Chapter 13: Health in the Annual Chart ────────────────────────────────
  { chapter: 13, verse: 1, content: "Health in the Tajaka annual chart is primarily assessed through three factors: (1) the annual Lagna and its lord's condition; (2) the 6H and 8H lords of the annual chart and any planets placed in those houses; (3) the Roga Sahama and Paka Sahama positions and aspects. All three must be considered together for a complete annual health assessment." },
  { chapter: 13, verse: 2, content: "The annual Lagna represents the native's body and physical vitality for the year. Malefics (Saturn, Mars, Rahu, Ketu) in the annual Lagna directly afflict the body: Saturn in the annual Lagna brings chronic fatigue, joint problems, or constitutional weakness; Mars brings accidents, fever, or surgical events; Rahu brings mysterious ailments, toxins, or atypical presentations." },
  { chapter: 13, verse: 3, content: "The 6H of the annual chart governs disease and its manifestation. The 6H lord's placement in the annual chart reveals the source or nature of health challenges: 6H lord in the annual 1H brings illness that directly affects the native's body and appearance; 6H lord in the annual 8H creates a 6-8 connection that brings chronic or serious health challenges." },
  { chapter: 13, verse: 4, content: "The 8H of the annual chart governs sudden health crises, surgical interventions, and transformation through health events. The 8H lord's condition and its Ithasala connections in the annual chart reveal whether the year brings health transformation (8H lord in Ithasala with a benefic — transformation leading to renewal) or crisis (8H lord in Ithasala with a malefic)." },
  { chapter: 13, verse: 5, content: "Roga Sahama (Part of Disease) afflicted in the annual chart — aspected by malefics, placed in the 6H or 8H of the annual chart, or with its lord debilitated — is a primary warning signal for health challenges in the year. When both the Roga Sahama and the 6H lord are afflicted in the same annual chart, health events are nearly certain." },
  { chapter: 13, verse: 6, content: "Paka Sahama (Part of Vitality/Digestion) afflicted in the annual chart indicates specific digestive, metabolic, or constitutional health concerns for the year. The nature of the afflicting malefic indicates the type: Saturn affliction to Paka Sahama brings slow metabolism, constipation, or bone-related issues; Mars brings inflammatory conditions, acidity, or fever." },
  { chapter: 13, verse: 7, content: "Muntha in the 6H or 8H of the annual chart is a primary health risk indicator. The annual sensitivity point in the house of disease or crisis intensifies health vulnerability throughout the year. This configuration is especially concerning when the Muntha lord is also afflicted or placed in another dusthana." },
  { chapter: 13, verse: 8, content: "Protective health factors in the annual chart: Jupiter in the annual Lagna, aspecting the Lagna, or in Ithasala with the annual Lagna lord provides the strongest annual health protection. The annual Lagna lord in an angle with high Harsha Bala maintains physical vitality. These protective factors can mitigate even severe 6H and 8H afflictions." },
  { chapter: 13, verse: 9, content: "The timing of health events within the annual period: health challenges typically manifest during the Mudda Dasha of the 6H or 8H lord of the annual chart, or when the Mudda Dasha lord is in Ithasala with a malefic planet in the annual chart. This timing technique allows prospective identification of vulnerable health windows within the year." },
  { chapter: 13, verse: 10, content: "Neelakantta's summary on annual health: the Tajaka system provides a more granular annual health assessment than the natal chart alone can offer. The natal chart shows constitutional predispositions; the Varsha Kundali shows which years activate those predispositions and which years provide protection. Both must be read together for complete health guidance." },

  // ── Chapter 14: Career and Finance in the Annual Chart ────────────────────
  { chapter: 14, verse: 1, content: "Career events in the annual chart are governed primarily by the 10H and 10H lord of the Varsha Kundali, the Karma Sahama, the Sun (natural significator of career and authority), and any Ithasala connecting these to the annual Lagna lord. The annual 10H is the year's career arena; the 10H lord is the career's operative agent for the year." },
  { chapter: 14, verse: 2, content: "The annual 10H lord in an angle of the annual chart with high Harsha Bala and in Ithasala with the Lagna lord indicates a year of active career advancement. The native's personal initiative directly connects to career outcomes. Job changes, promotions, or entrepreneurial breakthroughs typically occur in such years." },
  { chapter: 14, verse: 3, content: "The annual 10H lord in a dusthana (6H, 8H, 12H) indicates career challenges: 10H lord in 6H brings career-vs-service conflicts or workplace enemies; in 8H brings sudden career disruption or transformation; in 12H brings withdrawal from career or foreign-based work. The challenges can be transformative or merely uncomfortable depending on aspects." },
  { chapter: 14, verse: 4, content: "Karma Sahama in the annual 10H or 11H of the Varsha Kundali and aspected by the Sun or Mars brings career achievement as the year's primary external event. The native is recognized for their work, takes on increased responsibility, or completes a significant professional milestone. This configuration is the annual chart's career success indicator." },
  { chapter: 14, verse: 5, content: "Finance in the annual chart is primarily governed by the 2H and 11H of the Varsha Kundali, the 2H and 11H lords, and the Mahadasha Sahama (Part of Prosperity). Annual income themes are shown by the 2H (accumulated wealth) and 11H (incoming gains). The Mahadasha Sahama in the 2H or 11H with Venus aspecting is the annual wealth indicator." },
  { chapter: 14, verse: 6, content: "The annual 11H and its lord indicate the year's gains — income exceeding baseline, financial windfalls, and the fulfilment of financial wishes. The 11H lord in an angle with Venus or Jupiter aspecting it in the annual chart indicates a year of notable financial gains. The 11H lord in a dusthana with malefics aspecting indicates financial loss or unfulfilled financial hopes." },
  { chapter: 14, verse: 7, content: "Ithasala between the Varshesha and the 11H lord in the annual chart: the year lord directly supports financial gains. Whatever the Varshesha's nature, its energy is channelled into the 11H's domain — gains, network expansion, and wish fulfilment. This is a financially productive annual configuration." },
  { chapter: 14, verse: 8, content: "The annual 2H lord's condition governs the year's speech and family finance situation. Annual 2H lord afflicted by malefics in the Varsha Kundali: the year brings family financial pressures, disputes over wealth, or speech-related problems. Annual 2H lord well-placed and aspected by benefics: the year improves the family's financial baseline and brings harmonious family communications." },
  { chapter: 14, verse: 9, content: "Neelakantta's career-finance integration rule: the most productive career-finance years are those where both the 10H and 11H lords are strong and in Ithasala with each other or with the Lagna lord in the annual chart. Career achievement (10H) directly translating to financial gain (11H) is the optimal annual pattern." },
  { chapter: 14, verse: 10, content: "The Tajaka system's practical value for career-finance prediction: unlike natal chart analysis which shows lifetime potential, the Varsha Kundali shows which specific year the potential is activated. A natal raja yoga that has not manifested career-wise may do so in the year when the annual 10H lord forms Ithasala with the natal raja yoga planets in the annual chart." },

  // ── Chapter 15: Relationships and Marriage in the Annual Chart ────────────
  { chapter: 15, verse: 1, content: "Marriage and relationship events in the annual chart are governed by the 7H and 7H lord of the Varsha Kundali, Venus (natural significator of marriage and partnership), Dara Sahama, and any Ithasala connecting these to the Lagna lord. The annual 7H activates partnership themes; the annual 7H lord is the partnership's operative agent for the year." },
  { chapter: 15, verse: 2, content: "The annual 7H lord in an angle of the annual chart with Venus in Ithasala with the Lagna lord is the most reliable marriage event indicator in Tajaka. When this configuration appears in the annual chart during the natal Dasha and Antardasha that also indicate marriage, the event is considered certain by Neelakantta." },
  { chapter: 15, verse: 3, content: "The Dara Sahama in the annual 7H or 1H, aspected by Venus and Jupiter, confirms marriage or significant partnership events in the year. Dara Sahama in the 7H of the annual chart with the annual 7H lord also well-placed is a doubled indicator of the year's partnership activation." },
  { chapter: 15, verse: 4, content: "Venus in the annual Lagna or 7H with high Harsha Bala and in Ithasala with the annual 7H lord: the year brings romantic encounters, marriage decisions, or significant relationship deepening. The quality of the Venus-7H lord Ithasala (by dignity, house placement, and orb) determines the relationship's quality and permanence." },
  { chapter: 15, verse: 5, content: "Malefics in the annual 7H bring relationship tensions: Saturn in the annual 7H delays or limits partnership events — the year may bring relationship responsibility rather than romantic pleasure; Mars in the annual 7H brings conflict and passion in partnerships — relationships are intense but potentially turbulent; Rahu in the annual 7H brings unusual or foreign relationships." },
  { chapter: 15, verse: 6, content: "The annual 7H lord in Ishrafa from Venus in the annual chart indicates a partnership matter that has already peaked before the annual period. The native is in a relationship transition — a prior partnership is concluding or a relationship dynamic that was at its height in the prior year is now declining. New relationships begun in this Ishrafa year will not have the longevity of those begun in Ithasala years." },
  { chapter: 15, verse: 7, content: "Kambula Yoga involving Venus and Jupiter in the annual 1H and 7H axis creates an exceptionally favourable annual period for marriage and partnership. The double benefic presence across the relationship axis brings harmony, commitment, and mutual fulfilment to existing relationships and makes new partnerships formed in this year especially blessed." },
  { chapter: 15, verse: 8, content: "The Vivaha Sahama (Part of Marriage) specifically consulted for marriage events: when both the Dara Sahama and the Vivaha Sahama are in angular houses of the annual chart and aspected by Venus, the year's relationship activation is confirmed at two levels of Sahama analysis. This double Sahama confirmation is strong evidence for marriage events." },
  { chapter: 15, verse: 9, content: "Neelakantta's integrative principle for relationship prediction: the annual chart confirms or modifies the natal chart's marriage promise. If the natal chart shows marriage promise during a specific Dasha and the Varsha Kundali in that year also shows strong 7H activation, marriage in that specific year is highly probable. If the Varsha Kundali shows the 7H lord in 8H or 12H, the promised marriage may be delayed to the following year's annual period." },
  { chapter: 15, verse: 10, content: "The annual chart analysis of existing marriages: the annual 7H lord aspected by malefics in years of established marriage indicates strain, separation risk, or conflict in the partnership during the year. The annual 7H lord well-aspected by benefics in a stable marriage chart indicates a year of renewed closeness, shared achievement, or joyful partnership events." },

  // ── Chapter 16: Children and Creativity in the Annual Chart ───────────────
  { chapter: 16, verse: 1, content: "Children and creative events in the annual chart are governed by the 5H and 5H lord of the Varsha Kundali, Jupiter (natural significator of children and wisdom), and the Putra Sahama. When the annual 5H lord is in Ithasala with Jupiter or with the Lagna lord, children events (birth, conception, adoption, or a child's major milestone) occur in the annual period." },
  { chapter: 16, verse: 2, content: "The Putra Sahama in the annual 5H or in Ithasala with Jupiter and the annual 5H lord confirms children events in the year with high confidence. This Sahama confirmation is particularly useful when the natal chart shows children promise in the Dasha period — the Putra Sahama in the annual 5H confirms which specific year the promise activates." },
  { chapter: 16, verse: 3, content: "Creative achievement in the annual chart: the annual 5H lord in an angle with Mercury or Venus in Ithasala indicates a year of creative output — completion of an artistic work, publication, performance, or recognition of creative talent. The annual 5H combined with the annual 3H (communication) lord in Ithasala brings creative communication achievements." },
  { chapter: 16, verse: 4, content: "The annual 5H afflicted by Saturn indicates delayed or frustrated children and creative matters. A Saturn in the annual 5H may indicate a childless year despite natal promise, or creative work that is blocked or delayed by practical obstacles. The annual period counsels patience in children and creative matters when Saturn dominates the 5H." },
  { chapter: 16, verse: 5, content: "Jupiter in the annual 5H with high Harsha Bala is the most universally auspicious annual placement for children and creativity. Neelakantta considers this the best single-planet placement for the expansion of intelligence, creative gift, and children's wellbeing. Annual periods with this placement are remembered as creatively fertile and intellectually productive." },
  { chapter: 16, verse: 6, content: "The annual 5H lord in Ishrafa from Jupiter: a creative project or children-related matter that was at its height in the prior annual period is now declining or completing. The native may be finishing a creative work begun previously rather than beginning something new. A child born in the prior year is now established in the family; the excitement of new parenthood is settling into daily reality." },
  { chapter: 16, verse: 7, content: "Neelakantta's integrative guidance: the annual 5H analysis provides the timing for creative and children events that the natal chart has promised. The natal chart shows if children are promised at all; the Varsha Kundali shows in which year the promise is most accessible. Both must be consulted — the annual chart cannot create children promise absent from the natal chart, but it can identify the most favourable year to pursue the promise." },

  // ── Chapter 17: Spiritual Development in the Annual Chart ─────────────────
  { chapter: 17, verse: 1, content: "Spiritual development and dharmic activity in the annual chart are governed by the 9H and 12H of the Varsha Kundali, Jupiter (natural significator of dharma and wisdom), and the Yasha Sahama (reputation), Paradesa Sahama (foreign/spiritual), and the Muntha when it falls in the 9H or 12H of the annual chart." },
  { chapter: 17, verse: 2, content: "The annual 9H lord in an angle or trine with Jupiter in Ithasala brings a year of dharmic fulfilment — pilgrimage, spiritual study, teacher encounters, and expansion of philosophical understanding. The native experiences the year as spiritually productive and may make commitments to a spiritual path or deepen existing practices." },
  { chapter: 17, verse: 3, content: "The Muntha in the annual 12H or 9H signals a year when inner life and spiritual concerns take priority over external achievement. The native feels drawn to retreat, meditation, pilgrimage, or philosophical study. Career and relationship events are present but feel secondary to an inner pull toward meaning and transcendence." },
  { chapter: 17, verse: 4, content: "Jupiter in the annual 9H or aspecting the annual 9H lord is the most reliable spiritual development indicator in the annual chart. The annual period brings guru encounters, dharmic teachings, expanded philosophical vision, and fortune through righteous action. The native who acts with integrity in a Jupiter-9H annual period finds that dharmic action directly produces material results." },
  { chapter: 17, verse: 5, content: "The annual 12H and its lord govern loss, expenditure, foreign residence, and spiritual withdrawal. When the 12H lord is well-placed (in a trine or aspected by Jupiter) in the annual chart, the year's 12H matters (foreign travel, spiritual retreat, time in solitude) are voluntary and nourishing. When the 12H lord is in a dusthana and afflicted, the 12H matters become involuntary and draining — hospitalisation, imprisonment, or forced isolation." },
  { chapter: 17, verse: 6, content: "The Paradesa Sahama in the annual 12H or aspected by Saturn and Mercury: the year brings significant foreign involvement — travel to foreign lands, residence in a foreign country, or important professional dealings with foreigners. This may be experienced as adventurous or as exile depending on the quality of aspects to the Paradesa Sahama." },
  { chapter: 17, verse: 7, content: "Neelakantta's advice on spiritual years: the Tajaka system reveals when the annual period is optimally suited for spiritual investment. When the annual chart's 9H and 12H lords are both in favourable condition and Jupiter is active in the annual chart, the native should not squander the year on purely material pursuits — the annual period is a dharmic opportunity that will not recur for twelve years." },

  // ── Chapter 18: Dangers and Difficulties in the Annual Chart ──────────────
  { chapter: 18, verse: 1, content: "The annual chart reveals not only opportunities but also dangers and difficulties. Neelakantta identifies five primary danger configurations in the Varsha Kundali: (1) Varshesha in 8H; (2) Muntha in 8H; (3) annual Lagna lord in 8H with malefic aspect; (4) Rahu or Ketu in the annual Lagna; (5) Saturn-Mars mutual Ithasala involving the 8H lord." },
  { chapter: 18, verse: 2, content: "The 8H of the annual chart governs sudden reversals, crises, hidden dangers, and mortality-adjacent events. The 8H lord's placement and aspects in the annual chart reveal the nature of any annual dangers: 8H lord in 12H suggests hidden or foreign-related dangers; 8H lord in 6H suggests health crises from enemies or litigation; 8H lord in 1H suggests personal danger or transformation of identity." },
  { chapter: 18, verse: 3, content: "A malefic-dominated annual Lagna (Saturn, Mars, Rahu, Ketu all placed in or aspecting the annual Lagna) creates what Neelakantta calls a 'Peeda Lagna' — an afflicted self for the year. The native's body, personal initiative, and self-expression are directly challenged throughout the annual period. Protective measures (Jupiter's aspect or Venus in the annual Lagna) are especially valuable in Peeda Lagna years." },
  { chapter: 18, verse: 4, content: "The annual 3H governs courage and short journeys. When the annual 3H lord is afflicted by malefics and in Ithasala with the 8H lord, the annual period carries risk during travel — accidents during journeys, road incidents, or aviation-related dangers. Neelakantta advises caution during travel in such annual periods." },
  { chapter: 18, verse: 5, content: "Financial dangers in the annual chart: the 2H and 11H lords in Ishrafa from the annual Lagna lord with both in dusthanas signals a year of financial decline. The native may experience unexpected expenses, financial loss through deception, or a reversal of prior financial gains. Saturn-Rahu combination in the annual 2H or 11H intensifies financial danger." },
  { chapter: 18, verse: 6, content: "Legal difficulties in the annual chart: the annual 6H lord in Ithasala with a malefic and the annual 10H lord in a dusthana — combined — signals a year of legal disputes that affect professional standing. Mars in the annual 6H and Saturn in the annual 10H creates the 'litigation year' pattern in Tajaka analysis." },
  { chapter: 18, verse: 7, content: "Neelakantta's protective guidance for difficult annual periods: the annual chart reveals challenges in advance, giving the native the opportunity to exercise caution, seek protective remedies, and avoid high-risk activities during the vulnerable Mudda Dasha periods. The foreknowledge that Tajaka provides is itself a form of protection — the native who knows their annual dangers can navigate them with awareness." },
  { chapter: 18, verse: 8, content: "The most dangerous annual configuration in Neelakantta's assessment: Varshesha in 8H + Muntha in 8H + annual Lagna lord in 12H + malefic in annual Lagna. This four-factor danger convergence signals a year of multiple simultaneous challenges across health, finances, and identity. Even in such years, Jupiter's aspect on the annual Lagna or on the Varshesha can provide partial protection." },
  { chapter: 18, verse: 9, content: "Protection against annual dangers: annual Jupiter in the Lagna, 5H, or 9H provides the strongest general protection. The Varshesha in an angle despite being a malefic provides a degree of protection through its sheer strength — even a malefic year lord in an angle is better than a benefic year lord in a dusthana. The native's own virtuous action and dharmic commitment also strengthens the annual chart's protective factors." },
  { chapter: 18, verse: 10, content: "Summary: the Tajaka annual chart is a diagnostic tool for both opportunity and risk. Every annual period contains both — the skilled Tajaka practitioner identifies both dimensions and provides the native with a complete picture: where to invest energy for maximum return and where to exercise caution to avoid unnecessary harm." },

  // ── Chapter 19: Integration with Parashari Analysis ───────────────────────
  { chapter: 19, verse: 1, content: "The Tajaka annual chart does not operate independently of the natal chart — it operates as an annual lens placed over the natal chart's promises. Neelakantta establishes a hierarchy: (1) the natal chart reveals lifetime potential; (2) the Vimshottari Dasha reveals which decades and years are cosmically emphasised; (3) the Tajaka annual chart reveals which specific annual period within the Dasha is most activated." },
  { chapter: 19, verse: 2, content: "The natal chart's raja yogas can only manifest in years when the Varsha Kundali supports their activation. A natal Jupiter-Mercury raja yoga in the 5H and 9H axis will manifest most powerfully in annual periods when Jupiter or Mercury is the Varshesha, or when the annual 5H and 9H lords are in Ithasala in the Varsha Kundali." },
  { chapter: 19, verse: 3, content: "Vimshottari Dasha and Tajaka integration: when the Vimshottari Mahadasha and Antardasha lords are also prominent in the Varsha Kundali (as Varshesha, in the annual Lagna, or in Ithasala with the annual Lagna lord), the annual period becomes doubly activated. Events of exceptional life significance typically occur in years of this double activation." },
  { chapter: 19, verse: 4, content: "Annual charts during Saturn's Sade Sati (seven-and-a-half-year Saturn transit over the natal Moon sign, 12th from it, and 2nd from it): the Tajaka annual chart reveals which specific years within the Sade Sati are most challenging. Annual periods where Saturn is the Varshesha or Muntha lord during Sade Sati are especially intense — the native must exercise maximum discipline and patience." },
  { chapter: 19, verse: 5, content: "The natal 7H and the Navamsha Lagna's condition: when a marriage-promising natal configuration is present and the Vimshottari Antardasha lord is Venus or the 7H lord, the Tajaka annual chart for that year confirms the specific year of marriage. Without both the natal promise and the annual chart's confirmation, marriage prediction lacks the dual-layer grounding it requires." },
  { chapter: 19, verse: 6, content: "Neelakantta's integration rule: never predict from the Varsha Kundali alone. Always establish: (1) what the natal chart promises for the domain in question; (2) which Vimshottari period is active; (3) what the annual chart shows for the domain in this specific year. All three layers must align for high-confidence prediction. When only two of three align, the probability drops; when only one aligns, the prediction is unreliable." },
  { chapter: 19, verse: 7, content: "The annual chart deepens and refines, but cannot contradict, the natal chart's fundamental architecture. A natally weak 7H cannot be transformed into a marriage year by a strong Varsha Kundali 7H configuration alone. The annual chart is an amplifier and a timing tool — it activates what the natal chart promises; it cannot create what the natal chart has not laid out." },
  { chapter: 19, verse: 8, content: "Transit analysis integrated with Tajaka: major transits (Saturn and Jupiter transits over natal planets and angles) that coincide with strong Varsha Kundali Ithasala formations create the most event-dense years of a native's life. The convergence of transit, Vimshottari Dasha, and Tajaka Ithasala is the triple activation point where life's most significant events crystallise." },
  { chapter: 19, verse: 9, content: "Neelakantta acknowledges that the Tajaka system, originating from non-Vedic astronomical traditions, was integrated into the Hindu Jyotish framework by successive generations of scholars. This integration is not superficial — the Sahama system was adapted from Arabic Parts using the Jyotish house framework; the Varshesha concept was developed to parallel the Dasha lord concept; the Mudda Dasha was created to provide annual-period timing parallel to the Vimshottari sub-period sequence." },
  { chapter: 19, verse: 10, content: "The complementarity of Parashari and Tajaka: Parashari analysis is fundamentally natal (life-arc focused); Tajaka analysis is fundamentally annual (year-focused). They are not competing systems but complementary temporal scales. The skilled Jyotish practitioner uses both: Parashari for the lifetime narrative and the decade's tone, Tajaka for the specific annual chapter and its events." },

  // ── Chapter 20: Practical Methodology and Conclusion ─────────────────────
  { chapter: 20, verse: 1, content: "Neelakantta outlines the complete Tajaka reading methodology in ten steps: (1) erect the Varsha Kundali for the native's current place of residence at the moment of solar return; (2) identify the Varshesha by Harsha Bala; (3) assess the Varshesha's condition (house, dignity, aspects); (4) place the Muntha in the annual chart and assess its condition; (5) calculate all sixteen Sahamas and their house placements." },
  { chapter: 20, verse: 2, content: "Steps 6-10 of the complete Tajaka reading: (6) identify all Ithasala Yogas in the annual chart (applying aspects within combined orbs) and determine the matters they signify; (7) identify all Ishrafa Yogas and note completed or declining matters; (8) check for Nakta, Kambula, and Dutthottha Yogas; (9) calculate the Mudda Dasha sequence and map the Ithasalas to specific Mudda Dasha periods; (10) integrate with the natal chart and Vimshottari Dasha to produce a layered annual prediction." },
  { chapter: 20, verse: 3, content: "The annual reading's output should answer five questions: (1) What is the year's overall tone (Varshesha condition)? (2) What is the year's primary arena of activity (Muntha's house)? (3) What specific matters will come to fruition (Ithasala Yogas)? (4) What matters have already peaked (Ishrafa Yogas)? (5) When within the year do the key events occur (Mudda Dasha timing)?" },
  { chapter: 20, verse: 4, content: "The Tajaka system's precision depends on exact birth time. An error of 4 minutes in birth time shifts the annual Lagna by approximately 1 degree and can change the house placement of the Muntha. Neelakantta recommends birth time rectification using past annual chart events before applying Tajaka to future prediction. If birth time is uncertain, the system is less reliable and the practitioner should acknowledge this limitation." },
  { chapter: 20, verse: 5, content: "Ethical use of the Tajaka system: Neelakantta cautions against using annual chart analysis to create fear in the native. Even when the annual chart shows danger or difficulty, the practitioner's role is to inform and empower the native with awareness — not to create fatalistic paralysis. The annual chart reveals tendencies and probabilities; human effort, virtuous action, and protective practices can modify outcomes." },
  { chapter: 20, verse: 6, content: "The limitation of annual prediction: no annual chart analysis is 100% certain. The Tajaka system deals in probabilities activated by cosmic timing. The practitioner makes probabilistic assessments based on the strength of yogas, the dignity of planets, and the coherence of natal-annual chart integration. Claims of absolute certainty violate the intellectual integrity the Tajaka tradition demands." },
  { chapter: 20, verse: 7, content: "Neelakantta on the role of the practitioner's intuition: after mastering the mechanical analysis of the annual chart (Varshesha, Muntha, Sahamas, Yogas, Mudda Dasha), the skilled Tajaka practitioner develops an intuitive integration of all these factors. This intuition is not mystical — it is the accumulated pattern recognition of extensive experience applied to a specific native's unique annual configuration." },
  { chapter: 20, verse: 8, content: "The annual chart reading should always begin with a statement of the year's overall tone based on the Varshesha, move to the specific arena of activity based on the Muntha, then proceed to the domain-specific detail through Sahamas and Ithasala Yogas, and conclude with Mudda Dasha timing. This sequence — from general to specific, from structural to temporal — is the methodologically sound order of Tajaka analysis." },
  { chapter: 20, verse: 9, content: "Neelakantta's final caution: the Tajaka annual chart is not a substitute for accumulated life wisdom, sound judgment, and virtuous conduct. The annual chart reveals the cosmic weather of the year; how the native navigates that weather depends on their own readiness, adaptability, and moral compass. Astrology — annual or natal — illuminates the path; the native must walk it." },
  { chapter: 20, verse: 10, content: "Conclusion of the Tajaka Neelakanthi: Neelakantta concludes by stating that the Tajaka system, properly applied, is among the most practically useful of all Jyotish methods for near-term prediction. While the natal chart reveals the lifetime's blueprint, the annual chart reveals this year's chapter. A complete Jyotish reading honours both scales — the eternal and the immediate — with equal rigor and equal humility." },

  // ── Chapter 21: Ashtakavarga Applied to the Annual Chart ──────────────────
  { chapter: 21, verse: 1, content: "Neelakantta integrates the Ashtakavarga system with the Varsha Kundali for an additional layer of annual analysis. Each planet's Ashtakavarga bindus in the annual chart's signs reveal how much support that planet receives from the combined Ashtakavarga of all planets including the Ascendant." },
  { chapter: 21, verse: 2, content: "A planet with 5 or more bindus in its annual chart sign has strong Ashtakavarga support and delivers its annual promises with enhanced ease. A planet with 3 or fewer bindus is considered weak in Ashtakavarga terms and struggles to manifest its annual significations even if its Harsha Bala is otherwise adequate." },
  { chapter: 21, verse: 3, content: "The Sarvashtakavarga (combined Ashtakavarga of all planets) of the annual chart's 10H indicates the year's overall career support from the cosmos. When the annual 10H has 30 or more total Sarvashtakavarga bindus, the year is cosmically supportive of career advancement. Below 25 bindus, career advancement faces systemic resistance." },
  { chapter: 21, verse: 4, content: "Ashtakavarga of Jupiter in the annual chart deserves special attention: Jupiter's transit through signs during the annual period brings its benefic results most fully in signs where it has 5 or more Jupiter-column bindus. This allows month-by-month tracking of the year's Jupiter-signified benefits (wisdom, children, wealth, dharma) using Ashtakavarga timing." },
  { chapter: 21, verse: 5, content: "Saturn's Ashtakavarga applied to the annual chart: Saturn causes the most difficulty in annual chart signs where it has 3 or fewer Saturn-column bindus. The native should be especially cautious during the Mudda Dasha periods when Saturn is transiting annual-chart signs with low Ashtakavarga bindus — delays and obstacles intensify in those windows." },
  { chapter: 21, verse: 6, content: "The Ashtakavarga of the Varshesha in the annual chart: if the Varshesha planet has strong Ashtakavarga bindus in its own annual-chart sign, the year lord's delivery is reinforced by Ashtakavarga timing. A weak Varshesha in Ashtakavarga terms means the year lord's promise, though structurally present, lacks the sustained cosmic support to fully manifest." },
  { chapter: 21, verse: 7, content: "Neelakantta notes that Ashtakavarga is primarily a Parashari tool and should be applied to the annual chart with appropriate adaptation. The bindus from the annual chart are calculated using the annual chart's planet positions, not the natal positions. This means the annual Ashtakavarga is a distinct computation from the natal Ashtakavarga." },
  { chapter: 21, verse: 8, content: "Trikona reduction (Shodhana) of the annual Ashtakavarga: Neelakantta recommends applying the Trikona Shodhana and Ekadhipatya Shodhana to the annual Ashtakavarga to produce the Prashtarashtakavarga — the reduced bindu count that more precisely indicates karmic support in each house of the annual chart." },
  { chapter: 21, verse: 9, content: "Transit planets moving over annual chart planets in high-bindu signs during the year create especially productive periods. Jupiter transiting over the annual 10H lord in a sign where Jupiter has 6 bindus is an exceptionally supportive career transit within the year. Conversely, Saturn transiting over the annual Lagna lord in a sign with 2 bindus intensifies the year's personal challenges during that transit window." },
  { chapter: 21, verse: 10, content: "Summary of Ashtakavarga in Tajaka: it provides an additional layer of granularity beyond the five primary Tajaka Yogas and the Mudda Dasha. When Ashtakavarga timing aligns with Mudda Dasha activation and an active Ithasala Yoga, the annual period's events crystallise with highest precision. The three-factor convergence — Yoga + Dasha + Ashtakavarga — is the most precise event-timing tool available in the integrated Parashari-Tajaka system." },

  // ── Chapter 22: Tajaka and the Twelve Divisional Charts ───────────────────
  { chapter: 22, verse: 1, content: "Neelakantta extends Tajaka analysis to divisional charts computed for the annual solar return moment. The Navamsha (D9) of the Varsha Kundali is the most important annual divisional chart, providing depth analysis of relationships, dharma, and the quality of each annual-chart planet's delivery. The Dasamsha (D10) of the annual chart reveals career-domain precision." },
  { chapter: 22, verse: 2, content: "The annual Navamsha Lagna is the primary indicator of the year's spiritual and relational depth. When the annual Navamsha Lagna is the same as the natal Navamsha Lagna (a coincidence that occurs infrequently), the year carries exceptional personal depth — the native's highest potential is accessible in the outer as well as the inner dimension." },
  { chapter: 22, verse: 3, content: "Planets in their own Navamsha in the annual chart — a subset of what Parashari calls Vargottama — are doubly empowered. They can deliver their annual significations with unusual completeness. The annual Vargottama Varshesha is particularly notable: the year lord is maximally empowered and the year's dominant theme manifests at full strength." },
  { chapter: 22, verse: 4, content: "The annual Dasamsha (D10) reveals career events in fine detail. The annual Dasamsha 10H lord and its aspects confirm whether the career events signified by the annual D1 10H analysis will be promotions, entrepreneurial successes, public recognitions, or career transitions. Ithasala in the annual D10 involving the 10H lord confirms D1 career signals." },
  { chapter: 22, verse: 5, content: "The Saptamsha (D7) of the annual chart addresses children matters: when the annual Saptamsha 5H lord is in Ithasala with Jupiter in the annual Saptamsha, the annual period carries unusually strong children events. This divisional confirmation adds confidence to Putra Sahama and annual D1 5H analysis pointing toward children events." },
  { chapter: 22, verse: 6, content: "Neelakantta acknowledges that using multiple annual divisional charts is the work of the advanced Tajaka practitioner. The beginner should first master the annual D1 with its Varshesha, Muntha, Sahamas, and five principal Yogas before adding divisional analysis. Premature complexity leads to confusion rather than clarity." },
  { chapter: 22, verse: 7, content: "The annual Drekkana (D3) reveals siblings, courage, and short-journey events in the annual period. Annual Drekkana 3H lord in Ithasala with Mercury confirms sibling-related events or short-journey milestones that the annual D1 3H analysis suggests. The Drekkana confirms — it does not contradict — the D1 analysis." },
  { chapter: 22, verse: 8, content: "Summary of divisional charts in Tajaka: the annual Navamsha is always consulted for relationship and dharmic depth. The annual Dasamsha is consulted for career precision. Other divisionals are used by advanced practitioners to confirm or qualify specific domain predictions. All divisional analysis is subordinate to the annual D1 analysis — the D1 is the master chart; divisionals are its subordinate commentaries." },

  // ── Chapter 23: Compatibility of Annual Charts in Relationships ───────────
  { chapter: 23, verse: 1, content: "Tajaka extends to synastry between annual charts. When two people in a relationship compare their Varsha Kundalis for the same annual period, the overlap of their annual 7H activations reveals the relationship's annual compatibility. If both natives have their annual 7H lord in Ithasala with Venus in the same annual period, the year is propitious for partnership deepening." },
  { chapter: 23, verse: 2, content: "When one native's annual Varshesha aspects the other native's annual Lagna or 7H lord, the two annual charts are in positive resonance for the year. Their individual years harmonise — what benefits one benefits the other; their goals for the annual period are aligned. Such annual chart synastry supports shared ventures and deepening commitment." },
  { chapter: 23, verse: 3, content: "Conflicting annual charts between two people in a relationship: when one native's annual Saturn (as Varshesha) falls in the same degree as the other native's annual Venus or 7H lord, the year brings relationship tension from the misalignment of annual-chart energies. The Saturn-person feels burdened; the Venus-person feels constrained. Awareness of this annual conflict allows the couple to manage it consciously." },
  { chapter: 23, verse: 4, content: "The annual Muntha's interaction between two charts: when native A's Muntha and native B's Muntha are in the same sign in the same annual period, both natives are sensitive to the same annual-chart house and its themes. Shared Muntha years are characterised by a strong sense of shared experience and mutual understanding of each other's annual priorities." },
  { chapter: 23, verse: 5, content: "Neelakantta cautions that annual chart synastry is a refinement tool, not a primary compatibility indicator. The natal chart compatibility (Kundali Milap) remains primary for long-term relationship assessment. Annual chart synastry reveals the quality of the present year in the relationship context — whether it is a year for deepening or a year for challenge and growth through friction." },
  { chapter: 23, verse: 6, content: "The most auspicious annual chart synastry configuration: both partners have Jupiter in the annual 7H or aspecting their respective annual 7H lords simultaneously, and both partners have Dara Sahama in angular houses in the same annual period. This double-annual-chart Jupiter-7H convergence marks years of marriage, renewal of vows, or exceptional partnership harmony." },
  { chapter: 23, verse: 7, content: "Business partnerships evaluated through annual charts: when both partners' annual 7H lords are in mutual Ithasala in the annual period when they are considering forming a business partnership, the timing is cosmically supported. When the annual charts show Ishrafa in the 7H for both, it is not an auspicious year to begin a new business partnership — better to wait for the next year's annual chart evaluation." },

  // ── Chapter 24: Tajaka Remedies and Protective Measures ───────────────────
  { chapter: 24, verse: 1, content: "Neelakantta acknowledges the role of remedial measures (upayas) in addressing difficult annual chart configurations. While the Tajaka text's primary focus is prediction rather than remedy, it recognises that awareness of annual chart challenges enables protective action. Remedies strengthen the annual chart's weak planets and mitigate the effects of afflicted houses." },
  { chapter: 24, verse: 2, content: "For a weak or afflicted Varshesha: strengthening the year lord through its planet-specific remedies (gemstones, mantras, charitable acts associated with the planet) reinforces the year's overall vitality. Jupiter-Varshesha remedies involve yellow sapphire or topaz, chanting of Guru mantras, and charitable acts toward teachers and scholars." },
  { chapter: 24, verse: 3, content: "For Muntha in 8H: propitiating the Muntha lord (the planet ruling the sign Muntha occupies) reduces the 8H Muntha's adversity. If the Muntha is in Scorpio (ruled by Mars), Mars remedies — coral gemstone, Mangala mantra, service to soldiers or athletes, Tuesday fasts — strengthen the Muntha lord and mitigate the 8H placement's danger." },
  { chapter: 24, verse: 4, content: "For malefics in the annual Lagna: Jupiter's protection is invoked through Guru puja, Vishnu worship, or Brihaspati-related charitable acts performed at the annual period's start. Jupiter's natural protective quality is strengthened by invoking it consciously at the year's beginning — this is Tajaka's version of annual ritual protection." },
  { chapter: 24, verse: 5, content: "For Roga Sahama afflictions: Mercury and Moon remedies address the health domain's annual challenges (Mercury governs nervous system health; Moon governs emotional and fluid-related health). Green emerald for Mercury, pearl or moonstone for Moon, combined with appropriate dietary adjustments aligned with the afflicting malefic's nature." },
  { chapter: 24, verse: 6, content: "For financial difficulties shown in the annual 2H and 11H: Venus and Jupiter remedies address wealth domain challenges. Donation of food, clothing, or money on Friday (Venus) or Thursday (Jupiter) at the annual chart's period's opening activates the benefic protective principle. White diamond or white sapphire for Venus, yellow sapphire for Jupiter." },
  { chapter: 24, verse: 7, content: "Neelakantta's philosophical stance on remedies: they do not override karma — they strengthen the native's capacity to navigate the year's challenges with greater grace and less suffering. A difficult annual chart with strong remedial practice is navigated with awareness and support; without remedial practice, the same chart's challenges are met without buffer. Remedies increase resilience, not destiny." },
  { chapter: 24, verse: 8, content: "The most universally protective remedy for any difficult Varsha Kundali: regular Jupiter worship (Thursday puja), charitable acts toward Brahmin scholars and teachers, and reading of dharmic texts. Jupiter's natural protection, when invoked consciously at the annual period's opening, provides a baseline benefic influence that partially offsets even severe annual chart afflictions." },
  { chapter: 24, verse: 9, content: "Annual chart period-specific remedies: identifying the Mudda Dasha lord that governs the most challenging period within the year and performing that planet's remedies specifically during its Mudda Dasha period is more effective than generic annual remedies. The focused remedy during the specific challenging Mudda Dasha period provides timely and targeted protection." },
  { chapter: 24, verse: 10, content: "Summary on remedies in Tajaka: they are complementary to — not a substitute for — wise, informed action. The Tajaka practitioner who identifies annual challenges in advance gives the native two forms of protection: foreknowledge (so the native can act cautiously) and remedial practices (so the native can invoke protective cosmic energies). Together, these are Tajaka's most practical gift to the native." },

  // ── Chapter 25: Tajaka for Muhurta — Auspicious Annual Beginnings ──────────
  { chapter: 25, verse: 1, content: "Neelakantta extends Tajaka principles to Muhurta — the selection of auspicious moments for beginning important activities. When an important action is planned for the annual period, its timing within the year should align with an active Ithasala between planets relevant to that action. Beginning a new career venture during the Mudda Dasha period when the 10H lord is in Ithasala with the Varshesha maximises the venture's prospects." },
  { chapter: 25, verse: 2, content: "Marriage Muhurta and Tajaka: the most auspicious day within the annual period to solemnise a marriage is a day when the annual transit of Venus is aspecting the native's annual 7H lord and the Dara Sahama is within orb of a benefic transit. This day-level refinement within the annual period uses Tajaka principles to confirm the natal Muhurta selection." },
  { chapter: 25, verse: 3, content: "Property purchase Muhurta and Tajaka: the annual 4H lord's transit over auspicious degrees within the year, combined with Jupiter or Venus transiting the annual 4H in a high Ashtakavarga bindu period, identifies the optimal window for property purchase or home initiation within the annual period. The Tajaka annual chart narrows the Muhurta selection to specific monthly windows." },
  { chapter: 25, verse: 4, content: "Business commencement Muhurta within Tajaka: the optimal moment to begin a new business venture in the annual period is when the Mudda Dasha is of the annual 10H lord or Varshesha AND the Moon's transit is in a high-bindu sign aspected by Jupiter. This triple convergence — Mudda Dasha + Moon transit + high bindu — is the Tajaka Muhurta for business beginnings." },
  { chapter: 25, verse: 5, content: "Neelakantta's warning on Muhurta within difficult annual charts: no Muhurta within the annual period can fully overcome a severely afflicted Varsha Kundali for the same domain. If the annual 10H is severely afflicted (lord in 8H with malefics aspecting), no career-commencement Muhurta within that annual period will fully rescue the career thrust. The annual chart sets the year's ceiling; Muhurta determines where within the ceiling the native aims." },
  { chapter: 25, verse: 6, content: "Tajaka Muhurta for spiritual practice: the optimal moment within the annual period to begin a new spiritual practice or initiation is when the annual 9H lord and Jupiter are in Ithasala AND the Moon is in a nakshatra associated with the deity or tradition being invoked. This alignment ensures the practice takes root and persists through the annual period with sustained momentum." },
  { chapter: 25, verse: 7, content: "The Tajaka Muhurta principle extends to investment decisions within the annual period. When the annual 2H and 11H lords are in Ithasala AND Venus is transiting a high-bindu sign in the annual chart, financial investments initiated in that window have the best prospects for growth. The Muhurta for financial activity is not merely about avoiding malefic transits but about actively catching the Ithasala window." },
  { chapter: 25, verse: 8, content: "Summary of Tajaka Muhurta: the Varsha Kundali provides the annual chart's broad promise; Muhurta within the annual period identifies the optimal window to activate specific portions of that promise. Together they form a two-layer timing system: the annual chart shows the year's potential; Muhurta shows the optimal moment within the year to plant the seed that will grow into that potential's fulfilment." },

  // ── Chapter 26: Special Tajaka Configurations and their Results ────────────
  { chapter: 26, verse: 1, content: "Neelakantta describes a special configuration called Parivartana Ithasala: when planet A is in Ithasala with planet B AND planet A occupies planet B's sign while planet B occupies planet A's sign (a mutual reception). This double connection — Ithasala plus mutual reception — creates an extremely powerful annual activation. The matter signified by both planets manifests completely and emphatically in the annual period." },
  { chapter: 26, verse: 2, content: "The Subha Kartari Yoga in the annual chart: when the annual Lagna is hemmed between two benefics (one in the annual 12H and one in the annual 2H), the native's self-expression for the year is protected and beautified by benefic flanking. This configuration is particularly protective for health and personal image in the annual period." },
  { chapter: 26, verse: 3, content: "Papa Kartari Yoga in the annual chart: when the annual Lagna is hemmed between two malefics (one in the annual 12H and one in the annual 2H), the native's self-expression for the year is hemmed by malefic energy. This creates personal restriction, health vulnerability, and reduced self-efficacy throughout the annual period. Benefic aspect on the annual Lagna from Jupiter or Venus can partially break the hemming." },
  { chapter: 26, verse: 4, content: "The Kendra-Trikona combination in the annual chart: when the annual Kendra (angular house, 1H/4H/7H/10H) lord is in Ithasala with the annual Trikona (trine, 5H/9H) lord, a rajayoga equivalent forms in the annual chart. This is the annual chart's raja yoga — the year brings both material achievement (Kendra) and dharmic fulfilment (Trikona) simultaneously." },
  { chapter: 26, verse: 5, content: "Neechabhanga in the annual chart: when a planet is debilitated in the annual chart but its debilitation is cancelled by specific conditions (the debilitation lord is in an angle from the annual Lagna or Moon, or the exaltation lord of the debilitated planet is angular), the annual chart produces results of unexpected quality. The cancelled debilitation in the annual chart often brings dramatic reversals of fortune — difficult circumstances that ultimately resolve in the native's favour." },
  { chapter: 26, verse: 6, content: "The annual Gajakesari Yoga: Jupiter in angle from the annual Moon or the annual Lagna with Moon well-placed creates Gajakesari in the annual chart. Annual Gajakesari brings wisdom, public recognition, emotional intelligence, and general beneficence to the year. When the annual Moon is bright and in angular relationship to Jupiter in the annual chart, the year has an especially nourishing and culturally productive quality." },
  { chapter: 26, verse: 7, content: "The annual Parivartana Yoga (exchange of signs) between two planets in the annual chart amplifies their Ithasala: if Jupiter and Venus are in each other's signs in the annual chart AND are in Ithasala, the matter they signify is activated at maximum strength. Parivartana in the annual chart is equivalent to a strong natal Parivartana — both planets are empowered and mutually supportive." },
  { chapter: 26, verse: 8, content: "Annual Vipareeta Raja Yoga: when the annual 6H, 8H, and 12H lords are all placed in each other's houses (a three-way exchange of dusthana lords) in the Varsha Kundali, a Vipareeta-equivalent forms. The year begins with apparent difficulty and setbacks but resolves dramatically in the native's favour — circumstances that seemed catastrophic early in the year transform into unexpected opportunities by year-end." },
  { chapter: 26, verse: 9, content: "The annual Amala Yoga: the 10H from the annual Lagna or the annual Moon being occupied by a natural benefic (Jupiter, Venus, or unafflicted Mercury) creates Amala in the annual chart. The year brings spotless reputation in professional dealings, ethical recognition, and career advancement through the native's integrity rather than through cunning or force." },
  { chapter: 26, verse: 10, content: "The Mahapurusha Yogas in the annual chart: when a planet forms its Pancha Mahapurusha Yoga (own sign or exaltation in a Kendra) in the annual chart, even if it did not form this in the natal chart, the year carries the qualities of that Mahapurusha Yoga. A year with annual-chart Hamsa Yoga (Jupiter in own sign or exaltation in an annual Kendra) brings the year's character the wisdom, grace, and spiritual elevation associated with Hamsa." },
  { chapter: 26, verse: 11, content: "Neelakantta's final word on special configurations: the Varsha Kundali is as rich in combination and nuance as the natal chart. Every possible natal combination — raja yoga, Mahapurusha Yoga, Vipareeta Raja Yoga, Neechabhanga — can form in the annual chart and carry its significations for the one-year period. The annual chart is not a lesser chart than the natal chart; it is a different temporal scale of equal analytical richness." },
  { chapter: 26, verse: 12, content: "The completeness of Tajaka Neelakanthi: Neelakantta states that this text provides the complete foundation for annual chart analysis. The student who masters the Varshesha, the Muntha, the sixteen Sahamas, the five principal Yogas, the Mudda Dasha, the Ashtakavarga integration, the divisional chart extension, the annual synastry principles, the remedial framework, and the Muhurta application has all the tools required for acharya-grade annual chart delineation." },

  // ── Chapter 27: Annual Chart Timing — Day-by-Day Precision ────────────────
  { chapter: 27, verse: 1, content: "Tajaka's most detailed timing method uses the annual chart's Lagna transit. As the Earth rotates, the Lagna advances approximately 1° every 4 minutes (30° per 2 hours). In the annual chart, one complete Lagna cycle (360°) corresponds to one sidereal day. Sensitive degrees — exact positions of Ithasala planets, the Muntha, and major Sahamas — are activated when the annual Lagna transits over them." },
  { chapter: 27, verse: 2, content: "The annual Lagna transit over the exact degree of an Ithasala yoga activates that yoga's delivery with a precise daily window. If the annual Ithasala between Jupiter and the 10H lord falls at 15° Virgo, the day when the daily Lagna transits 15° Virgo (a specific hour and minute of that day) is the activation window for the career event promised by that Ithasala." },
  { chapter: 27, verse: 3, content: "The annual Lagna transit over the Muntha's exact degree creates a personal activation window — the native feels especially sensitive, significant events involving the self may occur, and the Muntha's house themes are temporarily intensified. These windows recur daily and are observed as particularly active personal periods." },
  { chapter: 27, verse: 4, content: "The Hora Lord (the planet governing each 1-hour period of the day based on the Jyotish Hora system) interacts with annual chart timing. When the Hora Lord matches the annual Varshesha, the hour is especially productive for matters of the year's dominant theme. Neelakantta recommends conducting important annual activities during Hora periods of the Varshesha." },
  { chapter: 27, verse: 5, content: "Monthly timing within the annual period: Neelakantta uses the Moon's monthly transit through the Varsha Kundali signs as a monthly timing tool. The month when the Moon transits over an annual Ithasala yoga's degree area is typically the calendar month when that yoga's matter manifests externally. This provides month-level precision within the annual framework." },
  { chapter: 27, verse: 6, content: "The Sun's monthly transit through annual chart houses provides a secondary timing layer. When the transiting Sun enters the annual chart house occupied by the Varshesha, that calendar month receives the year lord's most concentrated energy. Career-related matters (Sun's natural domain) are especially activated in the month when the Sun transits the annual 10H." },
  { chapter: 27, verse: 7, content: "Neelakantta identifies specific days within the Mudda Dasha periods as particularly eventful: the day when the Mudda Dasha lord's transit is within 1° of an annual Ithasala planet, AND the Moon is aspecting the annual Lagna or Varshesha, is a day of convergent activation — the most likely day within the annual period for that yoga's matter to crystallise into concrete events." },
  { chapter: 27, verse: 8, content: "The Sarvashtakavarga transit timing: during the annual period, when a planet (especially Jupiter or Saturn) transits through a sign with high Sarvashtakavarga bindus (25+) in the annual chart, that transit period brings the most productive window for the matters of that house. This monthly window is the annual chart's 'harvest period' for the transited house's domain." },
  { chapter: 27, verse: 9, content: "Tajaka day-timing integration with Panchangam: the annual chart's timing should always be cross-referenced with the natal Panchangam — Tithi, Vara, Nakshatra, Yoga, Karana. Days where the Tajaka timing activation coincides with an auspicious Panchangam combination (Siddha Yoga, Amrit Siddhi Yoga, or key Tithi of the native's natal Nakshatra deity) are the most auspicious days within the annual period for initiating important actions." },
  { chapter: 27, verse: 10, content: "Neelakantta's summary on day-by-day timing: while Tajaka provides annual and monthly-level precision through its primary tools (Varshesha, Muntha, Yogas, Mudda Dasha), day-level precision requires the integration of annual Lagna transit, Hora Lord, Moon transit, and Sarvashtakavarga timing. The astrologer who masters all four levels — annual, monthly, weekly, and daily — can provide the native with precise action windows throughout the year." },
  { chapter: 27, verse: 11, content: "The limitation of day-level Tajaka timing: such precision requires an exactly verified birth time (within 2 minutes). For natives with uncertain birth times, annual and monthly-level timing remain reliable, but day-level precision becomes unreliable. Neelakantta advises practitioners to state clearly the level of temporal precision their birth data supports." },
  { chapter: 27, verse: 12, content: "A worked example of Tajaka timing: Varshesha is Jupiter at 8° Sagittarius in the annual 10H. Ithasala with Mercury (annual 10H lord) at 15° Sagittarius exists. The month when the transiting Moon crosses 8°-15° Sagittarius is the primary career event month. The Mudda Dasha of Jupiter or Mercury provides the exact period. The day when the Hora Lord is Jupiter and the daily Lagna crosses 8°-15° Sagittarius is the most precise event window within the career month." },

  // ── Chapter 28: Case Studies and Illustrative Examples ────────────────────
  { chapter: 28, verse: 1, content: "Neelakantta illustrates Tajaka methodology through example charts. Example 1: A native with annual Varshesha = Venus at 5° Taurus in the annual 7H (own sign, angular) with Venus in Ithasala with the annual Lagna lord Mercury at 12° Taurus. The annual period brings marriage or partnership deepening — Venus's own sign strength plus angular placement plus Ithasala with Lagna lord is the triple confirmation of partnership events." },
  { chapter: 28, verse: 2, content: "Example 2: Annual Varshesha = Saturn at 28° Capricorn in the annual 10H (own sign, angular). Saturn in Ithasala with the 11H lord Jupiter at 15° Capricorn. The year brings career achievement (10H Saturn) that directly translates to financial gains (11H Jupiter). The matter requires patient effort (Saturn's nature) but culminates in solid, lasting professional and financial advancement by year-end." },
  { chapter: 28, verse: 3, content: "Example 3: Muntha at 22° Scorpio in the annual 8H. Muntha lord Mars in annual 12H conjunct Saturn. Varshesha = Moon in annual 6H (debilitated). This annual chart shows multiple danger indicators: 8H Muntha + Muntha lord in 12H conjunct Saturn + debilitated 6H Moon-Varshesha. The year requires exceptional caution regarding health, finances, and personal safety. Jupiter's aspect on the annual Lagna is the only protective factor." },
  { chapter: 28, verse: 4, content: "Example 4: Annual chart with Kambula Yoga — Jupiter at 3° Cancer (exaltation, annual 9H) in square aspect to Venus at 8° Libra (own sign, annual 12H). Both benefics in dignity; angular relationship creates Kambula. The annual period brings dharmic fulfilment (9H Jupiter) combined with artistic or relational refinement experienced through withdrawal or retreat (12H Venus). A spiritually and aesthetically nourishing year despite the 12H Venus placement." },
  { chapter: 28, verse: 5, content: "Example 5: Nakta Yoga case — annual chart where Mars (Lagna lord) at 20° Aries is in Ishrafa from Jupiter (5H lord) at 15° Aries (Mars already passed Jupiter). Mercury at 17° Aries (between them) in Ithasala with Jupiter at 15° Aries. Nakta: Mercury acts as intermediary. The 5H matter (creative project, children) arrives through a communication intermediary — a publisher for a creative work, a physician or counsellor for children matters. Mercury's mediation delivers what Mars's direct push could not." },
  { chapter: 28, verse: 6, content: "Example 6: Dutthottha Yoga case — Venus (7H lord) at 25° Libra in Ishrafa from Moon (Lagna lord) at 20° Libra. Jupiter at 18° Gemini aspects both Moon (trine to 20° Libra) and Venus (trine to 25° Libra). Jupiter acts as active advocate. The 7H matter (partnership) blocked by the Venus-Moon Ishrafa is rescued by Jupiter — a wise friend, spiritual teacher, or respected elder intervenes and facilitates the partnership that stalled. Jupiter's trine aspect (120°) carries the matter to completion." },
  { chapter: 28, verse: 7, content: "Example 7: Career-finance convergence case — annual 10H lord Mercury in Ithasala with annual 11H lord Mars, both in the annual 10H. Karma Sahama in annual 10H. Mahadasha Sahama in annual 11H. Four-factor convergence: 10H lord Ithasala + Karma Sahama in 10H + Mahadasha Sahama in 11H + annual Mars (11H lord) as the Ithasala receiver. The year brings career achievement that directly converts to substantial financial gain. Both the career action and the financial result are doubly confirmed through Sahama analysis." },
  { chapter: 28, verse: 8, content: "Example 8: Health crisis-and-recovery case — annual Lagna lord in Ishrafa from the 8H lord; Roga Sahama in annual 6H; Saturn transiting the annual 6H with 2 Ashtakavarga bindus. A convergence of Ishrafa (the personal energy has already peaked before the year began), Roga Sahama in 6H, and Saturn's low-bindu transit over the 6H creates a health-vulnerable annual period. The native's Mudda Dasha of Saturn (116 days) within the annual period is the most medically vulnerable window. Jupiter aspecting the annual Lagna mitigates but does not eliminate the health challenges." },
  { chapter: 28, verse: 9, content: "Example 9: Spiritual breakthrough year — annual 9H lord Jupiter (Varshesha) at 0° Sagittarius (own sign) in the annual 9H. Jupiter in Ithasala with Ketu at 5° Sagittarius (Ketu in own natural sign in Sagittarius traditions). Yasha Sahama in annual 9H. Moon in annual 12H aspected by Jupiter. The year brings a spiritual breakthrough of exceptional quality: Ketu's liberation impulse, amplified by Jupiter's dharmic expansion in own sign, with the 12H Moon adding contemplative depth. Mundane career and financial events are secondary; the year's primary gift is spiritual awakening." },
  { chapter: 28, verse: 10, content: "Neelakantta concludes the case studies by noting the pattern: in each example, three or more annual chart factors converge to confirm a specific result. Single-factor evidence is insufficient for confident Tajaka prediction. The practitioner should always look for the triple confirmation: (1) a primary annual chart structure (Varshesha/Muntha placement); (2) an Ithasala or Ishrafa Yoga involving relevant planets; (3) a Sahama confirmation in the relevant domain. When all three point to the same result, the prediction carries the confidence of acharya-grade Tajaka analysis." },
  { chapter: 28, verse: 11, content: "Final methodological reminder from Neelakantta: the Tajaka annual chart is not a self-contained oracle but a layer within the complete Jyotish analytical framework. Its analysis is always preceded by natal chart reading, always framed within the Vimshottari Dasha context, and always integrated with transit analysis. The Varsha Kundali adds annual precision to this multi-layer framework — it does not replace any of the other layers. The complete Jyotish reading of any question incorporates natal chart, Vimshottari Dasha, Tajaka annual chart, and relevant transits as four complementary lenses on a single luminous reality." },
];

